BUILTIN_MODULE_FILES: Dict[str, Dict[str, str]] = {'compute-event-worker': {'main.tf': '# ==============================================================================\n# STACKVEND: COMPUTE ARCHETYPE - EVENT WORKER (PUBSUB + CLOUD RUN JOB)\n# ==============================================================================\n# Provisions an asynchronous event processing worker backed by Google Cloud Pub/Sub\n# and a Cloud Run Job execution engine.\n# ==============================================================================\n\nlocals {\n  # EXP-4: name_suffix (optional) tells several event workers of one workload apart. Null or empty keeps the\n  # product-only names; a suffix is appended to the job, topic and subscription names as "-<suffix>".\n  name_base = replace(var.product_id, "_", "-")\n  name_stem = var.name_suffix == null || var.name_suffix == "" ? local.name_base : "${local.name_base}-${var.name_suffix}"\n}\n\nresource "google_pubsub_topic" "events" {\n  project      = var.project_id\n  name         = "events-${local.name_stem}"\n  kms_key_name = var.kms_key_name # lane 14 PR-0b: CMEK for regulated profiles (null = Google-managed)\n}\n\nresource "google_pubsub_subscription" "worker_sub" {\n  project              = var.project_id\n  name                 = "worker-sub-${local.name_stem}"\n  topic                = google_pubsub_topic.events.name\n  ack_deadline_seconds = 60\n}\n\nresource "google_cloud_run_v2_job" "worker" {\n  project             = var.project_id\n  name                = "worker-${local.name_stem}"\n  location            = var.region\n  deletion_protection = false\n\n  template {\n    task_count = 1\n\n    template {\n      service_account = var.service_account_email\n      encryption_key  = var.kms_key_name\n\n      containers {\n        image = var.container_image\n\n        resources {\n          limits = {\n            cpu    = var.cpu_limit\n            memory = var.memory_limit\n          }\n        }\n\n        env {\n          name  = "PROJECT_ID"\n          value = var.project_id\n        }\n        # StackVend CLOUDRUN-GOOGLE-CLOUD-PROJECT-ENV (owner 11-10): the project variable Google client libraries and\n        # most generated code read (Cloud Run sets none). This module takes no caller env, so the name is never doubled.\n        env {\n          name  = "GOOGLE_CLOUD_PROJECT"\n          value = var.project_id\n        }\n        env {\n          name  = "TOPIC_ID"\n          value = google_pubsub_topic.events.id\n        }\n      }\n    }\n  }\n}\n', 'outputs.tf': '# ==============================================================================\n# STACKVEND: COMPUTE ARCHETYPE - EVENT WORKER OUTPUTS\n# ==============================================================================\n\noutput "job_name" {\n  description = "Name of the Cloud Run v2 Job"\n  value       = google_cloud_run_v2_job.worker.name\n}\n\noutput "job_id" {\n  description = "ID of the Cloud Run v2 Job"\n  value       = google_cloud_run_v2_job.worker.id\n}\n\noutput "topic_name" {\n  description = "Pub/Sub Topic name"\n  value       = google_pubsub_topic.events.name\n}\n\noutput "topic_id" {\n  description = "Pub/Sub Topic ID"\n  value       = google_pubsub_topic.events.id\n}\n\noutput "subscription_name" {\n  description = "Pub/Sub Subscription name"\n  value       = google_pubsub_subscription.worker_sub.name\n}\n', 'variables.tf': '# ==============================================================================\n# STACKVEND: COMPUTE ARCHETYPE - EVENT WORKER VARIABLES\n# ==============================================================================\n\nvariable "project_id" {\n  description = "Target GCP Child Project ID"\n  type        = string\n}\n\nvariable "region" {\n  description = "GCP Region"\n  type        = string\n  default     = "us-central1"\n}\n\nvariable "product_id" {\n  description = "Workload Product ID"\n  type        = string\n}\n\nvariable "service_account_email" {\n  description = "Runtime service account email"\n  type        = string\n}\n\nvariable "container_image" {\n  description = "Container image URL"\n  type        = string\n  default     = ""\n}\n\nvariable "cpu_limit" {\n  description = "CPU limit for worker task"\n  type        = string\n  default     = "1000m"\n}\n\nvariable "memory_limit" {\n  description = "Memory limit for worker task"\n  type        = string\n  default     = "512Mi"\n}\n\nvariable "kms_key_name" {\n  description = "Cloud KMS CryptoKey resource name (CMEK) for the events topic and the worker job, in the worker\'s region. null = Google-managed encryption."\n  type        = string\n  default     = null\n}\n\nvariable "name_suffix" {\n  description = "Optional RFC 1123 label appended to the job, topic and subscription names as -<suffix>, so one workload can run several event workers. Null or empty keeps the product-only names."\n  type        = string\n  default     = null\n\n  validation {\n    condition     = var.name_suffix == null || can(regex("^([a-z0-9]([-a-z0-9]*[a-z0-9])?)?$", var.name_suffix))\n    error_message = "name_suffix must be empty or an RFC 1123 label: lowercase letters, digits and hyphens, starting and ending with a letter or digit."\n  }\n}\n'}, 'database-spanner': {'main.tf': '# ==============================================================================\n# STACKVEND: PARAMETERIZED MODULE - CLOUD SPANNER (TIER 2 STATEFUL)\n# ==============================================================================\n# Provisions an enterprise Cloud Spanner instance and optional database with\n# configurable processing units, CMEK support, and deletion protection defaults.\n# ==============================================================================\n\n# RT14-36: with `region` (the platform renders region = var.region) the instance configuration is regional-<region>,\n# never a literal and never a model\'s choice. RT14-F2 (owner 11-14, option a): a call without `region` (classic,\n# AI-written HCL) keeps its own `config` exactly as written, so an existing instance plans with no diff; the\n# compliance plan gate still checks it for regulated profiles. No data source: a read inside a module called with\n# depends_on = [module.foundation] is deferred to apply, which made `config` unknown at plan.\nlocals {\n  config       = var.region != null ? "regional-${var.region}" : var.config\n  instance_id  = var.instance_id != "" ? var.instance_id : "spanner-${replace(lower(var.product_id), "_", "-")}"\n  display_name = var.display_name != "" ? var.display_name : "Spanner Instance for ${var.product_id}"\n\n  default_labels = {\n    managed_by = "castor-terraform"\n    product_id = var.product_id\n  }\n}\n\nresource "google_spanner_instance" "instance" {\n  project          = var.project_id\n  name             = local.instance_id\n  config           = local.config\n  display_name     = local.display_name\n  processing_units = var.processing_units\n\n  labels = merge(local.default_labels, var.labels)\n\n  lifecycle {\n    precondition {\n      condition     = var.region != null ? (var.config == "" || var.config == local.config) : var.config != ""\n      error_message = "database-spanner: pass region = var.region and leave config empty (RT14-36: the configuration is then regional-<region>, so the instance stays in the workload region). With region set, config must be empty or exactly regional-<region>; without region, config must be set."\n    }\n  }\n}\n\nresource "google_spanner_database" "database" {\n  count               = var.database_name != "" ? 1 : 0\n  project             = var.project_id\n  instance            = google_spanner_instance.instance.name\n  name                = var.database_name\n  deletion_protection = var.deletion_protection\n  ddl                 = var.ddl_statements\n\n  # FD-4AZ-b1: only emit encryption_config when a CMEK key is given. An empty block (kms_key_name = null)\n  # fails the provider\'s "one of kms_key_name/kms_key_names" check at plan time.\n  dynamic "encryption_config" {\n    for_each = var.kms_key_name != null ? [1] : []\n    content {\n      kms_key_name = var.kms_key_name\n    }\n  }\n}\n', 'outputs.tf': 'output "instance_id" {\n  description = "The ID of the created Cloud Spanner instance."\n  value       = google_spanner_instance.instance.name\n}\n\noutput "instance_state" {\n  description = "The operational state of the Spanner instance."\n  value       = google_spanner_instance.instance.state\n}\n\noutput "database_id" {\n  description = "The name of the database created, if any."\n  value       = length(google_spanner_database.database) > 0 ? google_spanner_database.database[0].name : ""\n}\n\noutput "database_state" {\n  description = "The operational state of the Spanner database, if any."\n  value       = length(google_spanner_database.database) > 0 ? google_spanner_database.database[0].state : ""\n}\n', 'variables.tf': 'variable "project_id" {\n  description = "The GCP project ID to deploy the Cloud Spanner instance in."\n  type        = string\n}\n\nvariable "product_id" {\n  description = "StackVend product/workload identifier for labeling and naming defaults."\n  type        = string\n  default     = ""\n}\n\nvariable "instance_id" {\n  description = "The unique ID of the Cloud Spanner instance. If empty, derived from product_id."\n  type        = string\n  default     = ""\n}\n\nvariable "display_name" {\n  description = "The descriptive display name for the Spanner instance."\n  type        = string\n  default     = ""\n}\n\nvariable "region" {\n  description = "Workload region; the instance configuration is regional-<region> (RT14-36). Pass region = var.region. Null: config is used as written (RT14-F2) and must be set."\n  type        = string\n  default     = null\n}\n\nvariable "config" {\n  description = "Leave empty and pass region: the configuration is then regional-<region> (RT14-36, data residency); with region set, any other value is refused at plan. Without region it is used as written."\n  type        = string\n  default     = ""\n}\n\nvariable "processing_units" {\n  description = "Compute capacity allocated in processing units (1000 processing units = 1 node). Default 100 for cost efficiency."\n  type        = number\n  default     = 100\n}\n\nvariable "database_name" {\n  description = "Optional initial database name to create within the instance."\n  type        = string\n  default     = ""\n}\n\nvariable "ddl_statements" {\n  description = "Optional DDL statements to execute upon database creation."\n  type        = list(string)\n  default     = []\n}\n\nvariable "deletion_protection" {\n  description = "Block OpenTofu from deleting the Spanner database (FD-4AZ: on by default). Set false explicitly only for an ephemeral database you intend to destroy."\n  type        = bool\n  default     = true\n}\n\nvariable "kms_key_name" {\n  description = "Optional Cloud KMS CryptoKey resource name for CMEK encryption."\n  type        = string\n  default     = null\n}\n\nvariable "labels" {\n  description = "Key-value labels to attach to the Cloud Spanner instance."\n  type        = map(string)\n  default     = {}\n}\n'}, 'tasks-queue': {'main.tf': 'terraform {\n  required_version = ">= 1.5.0"\n  required_providers {\n    google = {\n      source = "hashicorp/google"\n    }\n  }\n}\n\nresource "google_cloud_tasks_queue" "queue" {\n  project  = var.project_id\n  location = var.region\n  name     = "${var.project_id}-${var.queue_name_suffix}"\n\n  rate_limits {\n    max_dispatches_per_second = var.max_dispatches_per_second\n    max_concurrent_dispatches = var.max_concurrent_dispatches\n  }\n\n  retry_config {\n    max_attempts = var.max_attempts\n  }\n}\n\nresource "google_cloud_tasks_queue_iam_member" "enqueuer" {\n  count    = var.workload_sa_email != "" ? 1 : 0\n  project  = var.project_id\n  location = var.region\n  name     = google_cloud_tasks_queue.queue.name\n  role     = "roles/cloudtasks.enqueuer"\n  member   = "serviceAccount:${var.workload_sa_email}"\n}\n', 'outputs.tf': 'output "queue_name" {\n  description = "Name of the Cloud Tasks queue"\n  value       = google_cloud_tasks_queue.queue.name\n}\n\noutput "queue_id" {\n  description = "Resource ID of the Cloud Tasks queue"\n  value       = google_cloud_tasks_queue.queue.id\n}\n', 'variables.tf': 'variable "project_id" {\n  description = "GCP Project ID"\n  type        = string\n}\n\nvariable "region" {\n  description = "GCP Region"\n  type        = string\n  default     = "us-central1"\n}\n\nvariable "queue_name_suffix" {\n  description = "Suffix for the Cloud Tasks queue name (e.g. \'webhooks\', \'background\')"\n  type        = string\n  default     = "tasks"\n}\n\nvariable "max_dispatches_per_second" {\n  description = "Maximum dispatch rate per second"\n  type        = number\n  default     = 100\n}\n\nvariable "max_concurrent_dispatches" {\n  description = "Maximum number of concurrent tasks dispatched"\n  type        = number\n  default     = 50\n}\n\nvariable "max_attempts" {\n  description = "Maximum retry attempts before sending to DLQ"\n  type        = number\n  default     = 5\n}\n\nvariable "workload_sa_email" {\n  description = "Workload service account email to grant enqueuer role"\n  type        = string\n  default     = ""\n}\n'}, 'compute-gce-bastion': {'main.tf': '# ==============================================================================\n# STACKVEND: COMPUTE ARCHETYPE - GCE BASTION (IAP PRIVATE JUMP HOST)\n# ==============================================================================\n# Provisions an e2-micro Google Compute Engine instance with NO external public IP.\n# Enforces OS Login and restricts SSH ingress exclusively to Google Cloud IAP CIDR.\n# Network (gce-bastion-network, the compute-gce-worker L10-u2 model): the workload\'s existing subnetwork when the\n# platform passes one (use_existing_subnetwork + subnetwork_id), else its own VPC + subnet on the IPAM fact\n# var.subnet_cidr with Private Google Access (Google APIs only: no external IP, no Cloud NAT, no internet). Neither\n# set: var.network / var.subnetwork exactly as before.\n# ==============================================================================\n\n# RT14-35: the VM\'s zone is var.zone when set, else the first zone of the workload region in sorted order (deterministic\n# per region; us-central1 keeps us-central1-a). Never a guessed "<region>-a": us-east1 and europe-west1 have none. No\n# status filter, like the typed-intent zone fact of the developer stage (ZONE_FACT_EXPR): the sorted list changes only\n# when Google adds a zone, so the zone of a running bastion stays put (a zone change would replace the VM).\n# RT14-F1: the platform render passes var.zone from a root read of the same list (no depends_on, so it is known at\n# plan even when the foundation has a pending change); the read below is the fallback for direct callers only.\ndata "google_compute_zones" "available" {\n  project = var.project_id\n  region  = var.region\n}\n\nlocals {\n  zone              = var.zone != "" ? var.zone : sort(data.google_compute_zones.available.names)[0]\n  net_base          = "bastion-${replace(substr(lower(replace(var.product_id, "_", "-")), 0, 40), "/-+$/", "")}"\n  own_network       = !var.use_existing_subnetwork && var.subnet_cidr != "" ? 1 : 0\n  own_net_id        = one(google_compute_network.bastion[*].id)\n  own_subnet_id     = one(google_compute_subnetwork.bastion[*].id)\n  legacy_subnetwork = var.subnetwork != "" ? var.subnetwork : null\n  # existing subnetwork: GCE takes the network from it; own: the own VPC; neither: var.network / var.subnetwork as before\n  vm_network    = var.use_existing_subnetwork ? null : (local.own_network == 1 ? local.own_net_id : var.network)\n  vm_subnetwork = var.use_existing_subnetwork ? var.subnetwork_id : (local.own_network == 1 ? local.own_subnet_id : local.legacy_subnetwork)\n}\n\n# SA-ACCOUNT-ID-TRIM: trailing dashes of the 18-character cut are dropped (an account_id cannot end in \'-\'); a cut\n# that does not end in \'-\' is unchanged.\nresource "google_service_account" "bastion_sa" {\n  project      = var.project_id\n  account_id   = "sa-bastion-${replace(substr(replace(var.product_id, "_", "-"), 0, 18), "/-+$/", "")}"\n  display_name = "IAP Bastion Service Account for ${var.product_id}"\n}\n\nresource "google_project_iam_member" "bastion_log_writer" {\n  project = var.project_id\n  role    = "roles/logging.logWriter"\n  member  = "serviceAccount:${google_service_account.bastion_sa.email}"\n}\n\nresource "google_project_iam_member" "bastion_metric_writer" {\n  project = var.project_id\n  role    = "roles/monitoring.metricWriter"\n  member  = "serviceAccount:${google_service_account.bastion_sa.email}"\n}\n\nresource "google_compute_network" "bastion" {\n  count                   = local.own_network\n  project                 = var.project_id\n  name                    = "${local.net_base}-net"\n  auto_create_subnetworks = false\n}\n\nresource "google_compute_subnetwork" "bastion" {\n  count                    = local.own_network\n  project                  = var.project_id\n  name                     = "${local.net_base}-subnet"\n  region                   = var.region\n  network                  = google_compute_network.bastion[0].id\n  ip_cidr_range            = var.subnet_cidr\n  private_ip_google_access = true\n\n  lifecycle {\n    ignore_changes = [secondary_ip_range]\n  }\n}\n\nresource "google_compute_instance" "bastion" {\n  project      = var.project_id\n  name         = "bastion-${replace(var.product_id, "_", "-")}"\n  machine_type = var.machine_type\n  zone         = local.zone\n\n  tags = ["bastion", "iap-ssh"]\n\n  boot_disk {\n    initialize_params {\n      image = var.boot_image\n    }\n  }\n\n  network_interface {\n    network    = local.vm_network\n    subnetwork = local.vm_subnetwork\n    # Zero public IP: access_config omitted intentionally (Google APIs through Private Google Access)\n  }\n\n  # The bastion\'s code (gce-bastion-startup): the platform passes `apps/<service>/startup.sh` as startup_script, the\n  # metadata key compute-gce-worker uses. Settings (gce-bastion-network): its topology resource bindings as instance\n  # metadata attributes, platform keys last. Both unset: the metadata is exactly { enable-oslogin = "TRUE" }.\n  metadata = merge(\n    var.settings,\n    var.startup_script == null ? {} : { "startup-script" = var.startup_script },\n    { "enable-oslogin" = "TRUE" },\n  )\n\n  service_account {\n    email  = google_service_account.bastion_sa.email\n    scopes = ["cloud-platform"]\n  }\n\n  lifecycle {\n    precondition {\n      condition     = !var.use_existing_subnetwork || var.subnetwork_id != ""\n      error_message = "compute-gce-bastion: use_existing_subnetwork needs subnetwork_id (projects/<p>/regions/<r>/subnetworks/<n>)."\n    }\n  }\n}\n\nresource "google_compute_firewall" "iap_ssh" {\n  project = var.project_id\n  name    = "allow-iap-ssh-${replace(var.product_id, "_", "-")}"\n  # The VM\'s own network: an existing subnetwork\'s network as the instance reports it, else the own VPC, else as before.\n  network = var.use_existing_subnetwork ? google_compute_instance.bastion.network_interface[0].network : (local.own_network == 1 ? local.own_net_id : var.network)\n\n  allow {\n    protocol = "tcp"\n    ports    = ["22"]\n  }\n\n  source_ranges = ["35.235.240.0/20"]\n  target_tags   = ["iap-ssh"]\n}\n\n# ------------------------------------------------------------------------------\n# Resource access: granted to the bastion\'s own SA, per resource (compute-gce-worker WORKER_RESOURCE_ACCESS roles)\n# ------------------------------------------------------------------------------\nresource "google_storage_bucket_iam_member" "bastion_bucket" {\n  count  = length(var.storage_buckets)\n  bucket = var.storage_buckets[count.index]\n  role   = "roles/storage.objectUser"\n  member = "serviceAccount:${google_service_account.bastion_sa.email}"\n}\n\nresource "google_pubsub_topic_iam_member" "bastion_topic" {\n  count   = length(var.pubsub_topics)\n  project = var.project_id\n  topic   = var.pubsub_topics[count.index]\n  role    = "roles/pubsub.publisher"\n  member  = "serviceAccount:${google_service_account.bastion_sa.email}"\n}\n\nresource "google_pubsub_subscription_iam_member" "bastion_subscription" {\n  count        = length(var.pubsub_subscriptions)\n  project      = var.project_id\n  subscription = var.pubsub_subscriptions[count.index]\n  role         = "roles/pubsub.subscriber"\n  member       = "serviceAccount:${google_service_account.bastion_sa.email}"\n}\n\nresource "google_secret_manager_secret_iam_member" "bastion_secret" {\n  count     = length(var.secrets)\n  project   = var.project_id\n  secret_id = var.secrets[count.index]\n  role      = "roles/secretmanager.secretAccessor"\n  member    = "serviceAccount:${google_service_account.bastion_sa.email}"\n}\n\nresource "google_bigquery_dataset_iam_member" "bastion_dataset" {\n  count      = length(var.bigquery_datasets)\n  project    = var.project_id\n  dataset_id = var.bigquery_datasets[count.index]\n  role       = "roles/bigquery.dataEditor"\n  member     = "serviceAccount:${google_service_account.bastion_sa.email}"\n}\n', 'outputs.tf': '# ==============================================================================\n# STACKVEND: COMPUTE ARCHETYPE - GCE BASTION OUTPUTS\n# ==============================================================================\n\noutput "instance_id" {\n  description = "Compute Engine instance ID"\n  value       = google_compute_instance.bastion.instance_id\n}\n\noutput "instance_name" {\n  description = "Compute Engine instance name"\n  value       = google_compute_instance.bastion.name\n}\n\noutput "instance_self_link" {\n  description = "URI of the bastion instance"\n  value       = google_compute_instance.bastion.self_link\n}\n\noutput "bastion_sa_email" {\n  description = "Service account email of the bastion instance"\n  value       = google_service_account.bastion_sa.email\n}\n', 'variables.tf': '# ==============================================================================\n# STACKVEND: COMPUTE ARCHETYPE - GCE BASTION VARIABLES\n# ==============================================================================\n\nvariable "project_id" {\n  description = "Target GCP Child Project ID"\n  type        = string\n}\n\nvariable "region" {\n  description = "GCP Region"\n  type        = string\n  default     = "us-central1"\n}\n\nvariable "product_id" {\n  description = "Workload Product ID"\n  type        = string\n}\n\nvariable "zone" {\n  description = "Zone of the bastion VM (empty: the first zone of var.region in sorted order, RT14-35)"\n  type        = string\n  default     = ""\n}\n\nvariable "machine_type" {\n  description = "GCE Machine Type"\n  type        = string\n  default     = "e2-micro"\n}\n\nvariable "boot_image" {\n  description = "OS Boot Disk Image"\n  type        = string\n  default     = "debian-cloud/debian-12"\n}\n\nvariable "network" {\n  description = "VPC network name"\n  type        = string\n  default     = "default"\n}\n\nvariable "subnetwork" {\n  description = "VPC subnetwork name (optional)"\n  type        = string\n  default     = ""\n}\n\nvariable "startup_script" {\n  description = "Startup script the VM runs at boot (the platform passes apps/<service>/startup.sh; null: none)"\n  type        = string\n  default     = null\n}\n\nvariable "subnet_cidr" {\n  description = "Own-subnet range: the platform IPAM fact var.subnet_cidr (never a literal); empty with no existing subnetwork: network / subnetwork as given"\n  type        = string\n  default     = ""\n}\n\nvariable "use_existing_subnetwork" {\n  description = "Join the workload\'s existing subnetwork (subnetwork_id) instead of creating a VPC + subnet"\n  type        = bool\n  default     = false\n}\n\nvariable "subnetwork_id" {\n  description = "Existing subnetwork id (projects/<p>/regions/<r>/subnetworks/<n>) when use_existing_subnetwork"\n  type        = string\n  default     = ""\n}\n\nvariable "settings" {\n  description = "Settings the startup script reads from instance metadata attributes (key -> value)"\n  type        = map(string)\n  default     = {}\n}\n\nvariable "storage_buckets" {\n  description = "Bucket names the bastion SA may read and write objects in (roles/storage.objectUser)"\n  type        = list(string)\n  default     = []\n}\n\nvariable "pubsub_topics" {\n  description = "Topic names the bastion SA may publish to (roles/pubsub.publisher)"\n  type        = list(string)\n  default     = []\n}\n\nvariable "pubsub_subscriptions" {\n  description = "Subscription names the bastion SA may pull from (roles/pubsub.subscriber)"\n  type        = list(string)\n  default     = []\n}\n\nvariable "secrets" {\n  description = "Secret ids the bastion SA may read (roles/secretmanager.secretAccessor)"\n  type        = list(string)\n  default     = []\n}\n\nvariable "bigquery_datasets" {\n  description = "Dataset ids the bastion SA may edit (roles/bigquery.dataEditor)"\n  type        = list(string)\n  default     = []\n}\n'}, 'ai-vertex-endpoint': {'main.tf': '# ==============================================================================\n# STACKVEND: PARAMETERIZED MODULE - VERTEX AI ENDPOINT (TIER 2 STATEFUL)\n# ==============================================================================\n# Provisions a managed Google Cloud Vertex AI Endpoint for machine learning\n# inference and foundation model serving.\n# ==============================================================================\n\nlocals {\n  endpoint_name = var.endpoint_name != "" ? var.endpoint_name : "endpoint-${replace(lower(var.product_id), "_", "-")}"\n  display_name  = var.display_name != "" ? var.display_name : (var.product_id != "" ? "Endpoint for ${var.product_id}" : local.endpoint_name)\n\n  default_labels = {\n    managed_by = "castor-terraform"\n    product_id = var.product_id\n  }\n}\n\nresource "google_vertex_ai_endpoint" "endpoint" {\n  project      = var.project_id\n  location     = var.region\n  name         = local.endpoint_name\n  display_name = local.display_name\n  description  = var.description\n  network      = var.network\n\n  dynamic "encryption_spec" {\n    for_each = var.kms_key_name != null ? [1] : []\n    content {\n      kms_key_name = var.kms_key_name\n    }\n  }\n\n  labels = merge(local.default_labels, var.labels)\n}\n', 'outputs.tf': 'output "endpoint_id" {\n  description = "The ID of the Vertex AI Endpoint."\n  value       = google_vertex_ai_endpoint.endpoint.id\n}\n\noutput "endpoint_name" {\n  description = "The name of the Vertex AI Endpoint."\n  value       = google_vertex_ai_endpoint.endpoint.name\n}\n', 'variables.tf': 'variable "project_id" {\n  description = "The GCP project ID to deploy the Vertex AI Endpoint in."\n  type        = string\n}\n\nvariable "region" {\n  description = "The GCP region to deploy the Vertex AI Endpoint in."\n  type        = string\n  default     = "us-central1"\n}\n\nvariable "product_id" {\n  description = "StackVend product/workload identifier for labeling and naming defaults."\n  type        = string\n  default     = ""\n}\n\nvariable "endpoint_name" {\n  description = "The resource name of the Vertex AI Endpoint. If empty, derived from product_id."\n  type        = string\n  default     = ""\n}\n\nvariable "display_name" {\n  description = "User-facing display name of the Vertex AI Endpoint."\n  type        = string\n  default     = ""\n}\n\nvariable "description" {\n  description = "The description of the Vertex AI Endpoint."\n  type        = string\n  default     = "Managed Vertex AI Endpoint provisioned by StackVend"\n}\n\nvariable "network" {\n  description = "Optional VPC network name/self-link for private service connect / direct peering."\n  type        = string\n  default     = null\n}\n\nvariable "kms_key_name" {\n  description = "Optional Cloud KMS CryptoKey resource name for customer-managed encryption."\n  type        = string\n  default     = null\n}\n\nvariable "labels" {\n  description = "Key-value labels to attach to the Vertex AI Endpoint."\n  type        = map(string)\n  default     = {}\n}\n'}, 'database-bigtable': {'main.tf': '# ==============================================================================\n# STACKVEND: PARAMETERIZED MODULE - CLOUD BIGTABLE (TIER 2 STATEFUL)\n# ==============================================================================\n# Provisions an enterprise Cloud Bigtable instance, cluster, and optional initial\n# table with column families.\n# ==============================================================================\n\nlocals {\n  instance_id  = var.instance_id != "" ? var.instance_id : "bigtable-${replace(lower(var.product_id), "_", "-")}"\n  display_name = var.display_name != "" ? var.display_name : "Bigtable Instance for ${var.product_id}"\n  cluster_id   = var.cluster_id != "" ? var.cluster_id : "${local.instance_id}-c1"\n\n  default_labels = {\n    managed_by = "castor-terraform"\n    product_id = var.product_id\n  }\n}\n\nresource "google_bigtable_instance" "instance" {\n  project             = var.project_id\n  name                = local.instance_id\n  display_name        = local.display_name\n  deletion_protection = var.deletion_protection\n\n  cluster {\n    cluster_id   = local.cluster_id\n    zone         = var.zone\n    num_nodes    = var.num_nodes\n    storage_type = var.storage_type\n  }\n\n  labels = merge(local.default_labels, var.labels)\n}\n\nresource "google_bigtable_table" "table" {\n  count         = var.table_name != "" ? 1 : 0\n  project       = var.project_id\n  name          = var.table_name\n  instance_name = google_bigtable_instance.instance.name\n\n  dynamic "column_family" {\n    for_each = toset(var.column_families)\n    content {\n      family = column_family.value\n    }\n  }\n}\n', 'outputs.tf': 'output "instance_id" {\n  description = "The ID of the Cloud Bigtable instance."\n  value       = google_bigtable_instance.instance.name\n}\n\noutput "cluster_id" {\n  description = "The ID of the Bigtable cluster."\n  value       = local.cluster_id\n}\n\noutput "table_id" {\n  description = "The ID of the created Bigtable table, if any."\n  value       = length(google_bigtable_table.table) > 0 ? google_bigtable_table.table[0].name : ""\n}\n', 'variables.tf': 'variable "project_id" {\n  description = "The GCP project ID to deploy Cloud Bigtable in."\n  type        = string\n}\n\nvariable "product_id" {\n  description = "StackVend product/workload identifier for labeling and naming defaults."\n  type        = string\n  default     = ""\n}\n\nvariable "instance_id" {\n  description = "The unique ID of the Cloud Bigtable instance. If empty, derived from product_id."\n  type        = string\n  default     = ""\n}\n\nvariable "display_name" {\n  description = "Descriptive display name for the Bigtable instance."\n  type        = string\n  default     = ""\n}\n\nvariable "cluster_id" {\n  description = "The unique ID of the primary Bigtable cluster. If empty, derived from instance_id."\n  type        = string\n  default     = ""\n}\n\nvariable "zone" {\n  description = "The GCP zone for the primary Bigtable cluster."\n  type        = string\n  default     = "us-central1-a"\n}\n\nvariable "num_nodes" {\n  description = "Number of nodes allocated to the Bigtable cluster. Default 1."\n  type        = number\n  default     = 1\n}\n\nvariable "storage_type" {\n  description = "Storage type for the cluster: \'SSD\' (recommended for low latency) or \'HDD\'."\n  type        = string\n  default     = "SSD"\n}\n\nvariable "deletion_protection" {\n  description = "Block OpenTofu from deleting the Bigtable instance (FD-4AZ: on by default). Set false explicitly only for an ephemeral instance you intend to destroy."\n  type        = bool\n  default     = true\n}\n\nvariable "table_name" {\n  description = "Optional initial Bigtable table to create."\n  type        = string\n  default     = ""\n}\n\nvariable "column_families" {\n  description = "Optional list of column family names to create in the initial table."\n  type        = list(string)\n  default     = []\n}\n\nvariable "labels" {\n  description = "Key-value labels to attach to the Bigtable instance."\n  type        = map(string)\n  default     = {}\n}\n'}, 'security-kms': {'main.tf': 'terraform {\n  required_version = ">= 1.5.0"\n  required_providers {\n    google = {\n      source = "hashicorp/google"\n    }\n    google-beta = {\n      source = "hashicorp/google-beta"\n    }\n  }\n}\n\nlocals {\n  keyring_name = "${var.project_id}-${var.keyring_name}"\n  # Lane 14 PR-0b: the key\'s Cloud KMS resource name, built from the same inputs the key ring and key below are\n  # created with (the provider\'s `google_kms_crypto_key.id` has exactly this form). It is known at plan time, so\n  # the compliance plan gate can verify every CMEK attribute that uses it before the first apply.\n  crypto_key_name = "projects/${var.project_id}/locations/${var.location}/keyRings/${local.keyring_name}/cryptoKeys/${var.key_name}"\n}\n\n# Lane 14 PR-0b: with enable_apis, the module enables Cloud KMS and the services whose agents use the key, so the\n# key ring and the service identities never race API enablement (disable_on_destroy = false: never turns an API off).\nresource "google_project_service" "required" {\n  for_each           = var.enable_apis ? toset(concat(["cloudkms.googleapis.com"], var.service_agent_services)) : toset([])\n  project            = var.project_id\n  service            = each.key\n  disable_on_destroy = false\n}\n\nresource "google_kms_key_ring" "keyring" {\n  project  = var.project_id\n  name     = local.keyring_name\n  location = var.location\n\n  depends_on = [google_project_service.required]\n}\n\nresource "google_kms_crypto_key" "key" {\n  name            = var.key_name\n  key_ring        = google_kms_key_ring.keyring.id\n  rotation_period = var.rotation_period\n\n  # Lane 14 PR-0b (owner option Q3): HSM-protected versions; no block = SOFTWARE (Cloud KMS default). The protection\n  # level is create-only: changing it later replaces the key (blocked by prevent_destroy).\n  dynamic "version_template" {\n    for_each = var.protection_level != "SOFTWARE" ? [1] : []\n    content {\n      algorithm        = "GOOGLE_SYMMETRIC_ENCRYPTION"\n      protection_level = var.protection_level\n    }\n  }\n\n  lifecycle {\n    prevent_destroy = true\n  }\n}\n\nresource "google_kms_crypto_key_iam_member" "encrypter_decrypter" {\n  count          = var.workload_sa_email != "" ? 1 : 0\n  crypto_key_id  = google_kms_crypto_key.key.id\n  role           = "roles/cloudkms.cryptoKeyEncrypterDecrypter"\n  member         = "serviceAccount:${var.workload_sa_email}"\n}\n\n# Lane 14 PR-0b: the Google service agent of each service that encrypts with this key (Artifact Registry,\n# Firestore, Cloud Run, ...). The agent is created (or read) through the Service Usage API and granted with the\n# provider\'s own typed `member` value ("serviceAccount:<agent email>"); no email is assembled here.\n# TI-5-G3b (owner 10-24): an agent the Service Usage identity API does not return is read from the dedicated data\n# source Google documents for it (closed table, the only exceptions): Cloud Storage (the project\'s Cloud Storage\n# service account). Its grant is an instance of service_agents below, so crypto_key_name (outputs.tf depends_on)\n# waits for it too.\nlocals {\n  dedicated_agent_services = ["storage.googleapis.com"]\n  gcs_agent_requested      = contains(var.service_agent_services, "storage.googleapis.com")\n  dedicated_agent_members = merge(\n    local.gcs_agent_requested ? { "storage.googleapis.com" = data.google_storage_project_service_account.gcs[0].member } : {},\n  )\n}\n\nresource "google_project_service_identity" "agents" {\n  provider = google-beta\n  for_each = setsubtract(toset(var.service_agent_services), local.dedicated_agent_services)\n  project  = var.project_id\n  service  = each.key\n\n  depends_on = [google_project_service.required]\n}\n\ndata "google_storage_project_service_account" "gcs" {\n  count   = local.gcs_agent_requested ? 1 : 0\n  project = var.project_id\n\n  depends_on = [google_project_service.required]\n}\n\nresource "google_kms_crypto_key_iam_member" "service_agents" {\n  for_each      = toset(var.service_agent_services)\n  crypto_key_id = google_kms_crypto_key.key.id\n  role          = "roles/cloudkms.cryptoKeyEncrypterDecrypter"\n  member = (contains(local.dedicated_agent_services, each.key) ? local.dedicated_agent_members[each.key]\n  : google_project_service_identity.agents[each.key].member)\n}\n', 'outputs.tf': 'output "keyring_id" {\n  description = "Resource ID of the KMS Keyring"\n  value       = google_kms_key_ring.keyring.id\n}\n\noutput "crypto_key_id" {\n  description = "Resource ID of the KMS CryptoKey"\n  value       = google_kms_crypto_key.key.id\n}\n\n# Lane 14 PR-0b: the CMEK input of every platform-wired golden module. Known at plan time; a consumer that\n# references it waits for the key and every service-agent grant (depends_on), so no resource is created with the\n# key before its service agent may use it.\noutput "crypto_key_name" {\n  description = "Cloud KMS resource name of the CryptoKey (known at plan time)"\n  value       = local.crypto_key_name\n  depends_on = [\n    google_kms_crypto_key.key,\n    google_kms_crypto_key_iam_member.encrypter_decrypter,\n    google_kms_crypto_key_iam_member.service_agents,\n  ]\n  precondition {\n    condition     = google_kms_crypto_key.key.id == local.crypto_key_name\n    error_message = "The created CryptoKey id differs from the computed crypto_key_name."\n  }\n}\n', 'variables.tf': 'variable "project_id" {\n  description = "GCP Project ID"\n  type        = string\n}\n\nvariable "location" {\n  description = "KMS Keyring Location (e.g. \'us-central1\' or \'global\')"\n  type        = string\n  default     = "us-central1"\n}\n\nvariable "keyring_name" {\n  description = "Name suffix for the KMS Keyring"\n  type        = string\n  default     = "keyring"\n}\n\nvariable "key_name" {\n  description = "Name for the KMS CryptoKey"\n  type        = string\n  default     = "workload-cmek"\n}\n\nvariable "rotation_period" {\n  description = "Automated key rotation period in seconds (e.g. \'7776000s\' for 90 days)"\n  type        = string\n  default     = "7776000s"\n}\n\nvariable "workload_sa_email" {\n  description = "Workload service account email to grant encrypter/decrypter role"\n  type        = string\n  default     = ""\n}\n\nvariable "service_agent_services" {\n  description = "Google APIs whose service agents are granted roles/cloudkms.cryptoKeyEncrypterDecrypter on the key (e.g. artifactregistry.googleapis.com). Default: none."\n  type        = list(string)\n  default     = []\n  # TI-5-G3b: only agents this module can grant (identity API, or the dedicated table in main.tf); anything else\n  # would plan and then fail at apply with an empty member.\n  validation {\n    condition = alltrue([for s in var.service_agent_services : contains([\n      "aiplatform.googleapis.com", "alloydb.googleapis.com", "artifactregistry.googleapis.com",\n      "container.googleapis.com", "firestore.googleapis.com", "pubsub.googleapis.com", "redis.googleapis.com",\n      "run.googleapis.com", "secretmanager.googleapis.com", "spanner.googleapis.com", "sqladmin.googleapis.com",\n      "storage.googleapis.com",\n    ], s)])\n    error_message = "service_agent_services: the module grants only aiplatform, alloydb, artifactregistry, container, firestore, pubsub, redis, run, secretmanager, spanner, sqladmin and storage (.googleapis.com)."\n  }\n}\n\nvariable "protection_level" {\n  description = "Protection level of the key\'s versions: SOFTWARE (default) or HSM. Create-only: set it before the first apply."\n  type        = string\n  default     = "SOFTWARE"\n  validation {\n    condition     = contains(["SOFTWARE", "HSM"], var.protection_level)\n    error_message = "protection_level must be SOFTWARE or HSM."\n  }\n}\n\nvariable "enable_apis" {\n  description = "Enable cloudkms.googleapis.com and every service_agent_services API from this module (never disabled on destroy)."\n  type        = bool\n  default     = false\n}\n'}, 'analytics-bigquery': {'main.tf': 'terraform {\n  required_version = ">= 1.5.0"\n  required_providers {\n    google = {\n      source = "hashicorp/google"\n    }\n  }\n}\n\nresource "google_bigquery_dataset" "dataset" {\n  project                    = var.project_id\n  dataset_id                 = var.dataset_id\n  location                   = var.region\n  delete_contents_on_destroy = var.delete_contents_on_destroy\n  description                = "Serverless BigQuery dataset managed by StackVend"\n\n  # Lane 14 PR-0b: default CMEK for the dataset\'s tables (no block = Google-managed encryption).\n  dynamic "default_encryption_configuration" {\n    for_each = var.kms_key_name != null ? [1] : []\n    content {\n      kms_key_name = var.kms_key_name\n    }\n  }\n}\n\nresource "google_bigquery_dataset_access" "workload_editor" {\n  count         = var.workload_sa_email != "" ? 1 : 0\n  project       = var.project_id\n  dataset_id    = google_bigquery_dataset.dataset.dataset_id\n  role          = "roles/bigquery.dataEditor"\n  user_by_email = var.workload_sa_email\n}\n', 'outputs.tf': 'output "dataset_id" {\n  description = "Identifier of the BigQuery dataset"\n  value       = google_bigquery_dataset.dataset.dataset_id\n}\n\noutput "dataset_name" {\n  description = "Fully qualified ID of the dataset"\n  value       = google_bigquery_dataset.dataset.id\n}\n', 'variables.tf': 'variable "project_id" {\n  description = "GCP Project ID"\n  type        = string\n}\n\nvariable "region" {\n  description = "BigQuery Dataset Region/Location"\n  type        = string\n  default     = "us-central1"\n}\n\nvariable "dataset_id" {\n  description = "Dataset ID (letters, numbers, underscores)"\n  type        = string\n  default     = "analytics"\n}\n\nvariable "delete_contents_on_destroy" {\n  description = "Delete all tables when dataset is destroyed"\n  type        = bool\n  default     = true\n}\n\nvariable "workload_sa_email" {\n  description = "Workload service account email to grant dataEditor role"\n  type        = string\n  default     = ""\n}\n\nvariable "kms_key_name" {\n  description = "Cloud KMS CryptoKey resource name for the dataset\'s default table encryption (CMEK), in the dataset\'s location. The BigQuery encryption service account needs roles/cloudkms.cryptoKeyEncrypterDecrypter on it. null = Google-managed encryption."\n  type        = string\n  default     = null\n}\n'}, 'networking-vpc': {'main.tf': 'terraform {\n  required_version = ">= 1.5.0"\n  required_providers {\n    google = {\n      source  = "hashicorp/google"\n      version = ">= 5.0.0"\n    }\n    google-beta = {\n      source  = "hashicorp/google-beta"\n      version = ">= 5.0.0"\n    }\n  }\n}\n\n# ------------------------------------------------------------------------------\n# 1. Core Virtual Private Cloud (VPC) Network\n# ------------------------------------------------------------------------------\nresource "google_compute_network" "vpc" {\n  project                 = var.project_id\n  name                    = var.network_name\n  auto_create_subnetworks = false\n  routing_mode            = "GLOBAL"\n  description             = "Enterprise Google Cloud VPC Network managed by StackVend"\n}\n\n# ------------------------------------------------------------------------------\n# 2. Primary Subnetwork (Anchor Region)\n# ------------------------------------------------------------------------------\nresource "google_compute_subnetwork" "primary" {\n  project                  = var.project_id\n  name                     = "${var.network_name}-${var.region}-subnet"\n  ip_cidr_range            = var.primary_subnet_cidr\n  region                   = var.region\n  network                  = google_compute_network.vpc.id\n  private_ip_google_access = true\n  description              = "Primary subnetwork in ${var.region} with Private Google Access"\n\n  dynamic "log_config" {\n    for_each = var.enable_flow_logs ? [1] : []\n    content {\n      aggregation_interval = "INTERVAL_5_SEC"\n      flow_sampling        = 0.5\n      metadata             = "INCLUDE_ALL_METADATA"\n    }\n  }\n  lifecycle {\n    ignore_changes = [secondary_ip_range]\n  }\n}\n\n# ------------------------------------------------------------------------------\n# 3. Additional Multi-Region Subnetworks (On-Demand Expansion)\n# ------------------------------------------------------------------------------\nresource "google_compute_subnetwork" "additional" {\n  for_each                 = var.additional_regions\n  project                  = var.project_id\n  name                     = "${var.network_name}-${each.key}-subnet"\n  ip_cidr_range            = each.value\n  region                   = each.key\n  network                  = google_compute_network.vpc.id\n  private_ip_google_access = true\n  description              = "Multi-region subnetwork in ${each.key} with Private Google Access"\n\n  dynamic "log_config" {\n    for_each = var.enable_flow_logs ? [1] : []\n    content {\n      aggregation_interval = "INTERVAL_5_SEC"\n      flow_sampling        = 0.5\n      metadata             = "INCLUDE_ALL_METADATA"\n    }\n  }\n  lifecycle {\n    ignore_changes = [secondary_ip_range]\n  }\n}\n\n# ------------------------------------------------------------------------------\n# 4. Private Services Access (PSA) Peering for Cloud SQL, Redis & AlloyDB\n# ------------------------------------------------------------------------------\nresource "google_compute_global_address" "private_service_access" {\n  count         = var.enable_private_service_access ? 1 : 0\n  project       = var.project_id\n  name          = "${var.network_name}-psa-range"\n  purpose       = "VPC_PEERING"\n  address_type  = "INTERNAL"\n  address       = var.psa_address # TI-5-F4: the platform IPAM range; null = Google allocates (unchanged)\n  prefix_length = var.psa_prefix_length\n  network       = google_compute_network.vpc.id\n  description   = "Reserved internal IP address block for Google Cloud Private Services Access (Cloud SQL, Redis, AlloyDB)"\n}\n\nresource "google_service_networking_connection" "private_vpc_connection" {\n  count                   = var.enable_private_service_access ? 1 : 0\n  network                 = google_compute_network.vpc.id\n  service                 = "servicenetworking.googleapis.com"\n  reserved_peering_ranges = [google_compute_global_address.private_service_access[0].name]\n}\n\n# ------------------------------------------------------------------------------\n# 5. Cloud NAT & Cloud Router (Optional Egress Gateway)\n# ------------------------------------------------------------------------------\nlocals {\n  nat_regions = var.enable_nat ? distinct(concat([var.region], keys(var.additional_regions))) : []\n}\n\nresource "google_compute_router" "nat_router" {\n  for_each = toset(local.nat_regions)\n  project  = var.project_id\n  name     = "${var.network_name}-${each.key}-router"\n  region   = each.key\n  network  = google_compute_network.vpc.id\n\n  bgp {\n    asn = 64514\n  }\n}\n\nresource "google_compute_router_nat" "nat_gateway" {\n  for_each                           = toset(local.nat_regions)\n  project                            = var.project_id\n  name                               = "${var.network_name}-${each.key}-nat"\n  router                             = google_compute_router.nat_router[each.key].name\n  region                             = each.key\n  nat_ip_allocate_option             = "AUTO_ONLY"\n  source_subnetwork_ip_ranges_to_nat = "ALL_SUBNETWORKS_ALL_IP_RANGES"\n\n  log_config {\n    enable = true\n    filter = "ERRORS_ONLY"\n  }\n}\n\n# ------------------------------------------------------------------------------\n# 6. Hardened Baseline Firewall Rules\n# ------------------------------------------------------------------------------\nresource "google_compute_firewall" "allow_internal" {\n  project     = var.project_id\n  name        = "${var.network_name}-allow-internal"\n  network     = google_compute_network.vpc.name\n  description = "Permit internal east-west traffic between all subnets in the VPC"\n\n  allow {\n    protocol = "icmp"\n  }\n  allow {\n    protocol = "tcp"\n    ports    = ["0-65535"]\n  }\n  allow {\n    protocol = "udp"\n    ports    = ["0-65535"]\n  }\n\n  source_ranges = concat([var.primary_subnet_cidr], values(var.additional_regions))\n}\n\nresource "google_compute_firewall" "allow_health_checks" {\n  project     = var.project_id\n  name        = "${var.network_name}-allow-health-checks"\n  network     = google_compute_network.vpc.name\n  description = "Permit Google Cloud Load Balancer and Cloud Run health check probes"\n\n  allow {\n    protocol = "tcp"\n  }\n\n  source_ranges = ["35.191.0.0/16", "130.211.0.0/22"]\n}\n\nresource "google_compute_firewall" "allow_iap" {\n  project     = var.project_id\n  name        = "${var.network_name}-allow-iap"\n  network     = google_compute_network.vpc.name\n  description = "Permit Google Cloud Identity-Aware Proxy (IAP) management tunneling without public bastion IPs"\n\n  allow {\n    protocol = "tcp"\n    ports    = ["22", "80", "443", "8080"]\n  }\n\n  source_ranges = ["35.235.240.0/20"]\n}\n', 'outputs.tf': '# ==============================================================================\n# STACKVEND: NETWORKING ARCHETYPE - ENTERPRISE VPC NETWORK OUTPUTS\n# ==============================================================================\n\noutput "network_id" {\n  description = "The unique identifier of the VPC network"\n  value       = google_compute_network.vpc.id\n}\n\noutput "network_name" {\n  description = "The name of the VPC network"\n  value       = google_compute_network.vpc.name\n}\n\noutput "network_self_link" {\n  description = "The URI of the VPC network"\n  value       = google_compute_network.vpc.self_link\n}\n\noutput "primary_subnetwork_id" {\n  description = "The unique identifier of the primary regional subnetwork"\n  value       = google_compute_subnetwork.primary.id\n}\n\noutput "primary_subnetwork_name" {\n  description = "The name of the primary regional subnetwork"\n  value       = google_compute_subnetwork.primary.name\n}\n\noutput "primary_subnetwork_cidr" {\n  description = "The IPv4 CIDR range of the primary subnetwork"\n  value       = google_compute_subnetwork.primary.ip_cidr_range\n}\n\noutput "additional_subnetwork_ids" {\n  description = "Map of secondary region names to their respective subnetwork IDs"\n  value       = { for k, v in google_compute_subnetwork.additional : k => v.id }\n}\n\noutput "psa_connection_id" {\n  description = "Identifier of the Private Services Access peering connection (null if disabled)"\n  value       = length(google_service_networking_connection.private_vpc_connection) > 0 ? google_service_networking_connection.private_vpc_connection[0].id : null\n}\n', 'variables.tf': '# ==============================================================================\n# STACKVEND: NETWORKING ARCHETYPE - ENTERPRISE VPC NETWORK VARIABLES\n# ==============================================================================\n\nvariable "project_id" {\n  description = "Target GCP Child Project ID"\n  type        = string\n}\n\nvariable "network_name" {\n  description = "Name of the Virtual Private Cloud (VPC) network"\n  type        = string\n  default     = "main-vpc"\n}\n\nvariable "region" {\n  description = "Primary anchor GCP Region for the core subnetwork"\n  type        = string\n  default     = "us-central1"\n}\n\nvariable "primary_subnet_cidr" {\n  description = "IPv4 CIDR block for the primary regional subnetwork"\n  type        = string\n  default     = "10.10.0.0/24"\n}\n\nvariable "additional_regions" {\n  description = "Map of secondary GCP regions to their respective subnet CIDR ranges (e.g., {\'us-east4\' = \'10.20.0.0/24\', \'us-west1\' = \'10.30.0.0/24\'})"\n  type        = map(string)\n  default     = {}\n}\n\nvariable "enable_private_service_access" {\n  description = "Whether to reserve an internal IP range and configure Private Services Access (PSA) peering for managed databases (Cloud SQL, Redis, AlloyDB)"\n  type        = bool\n  default     = true\n}\n\nvariable "psa_prefix_length" {\n  description = "Prefix length of the IP range reserved for Private Services Access (default /16 supports 65,536 internal IP addresses)"\n  type        = number\n  default     = 16\n}\n\nvariable "psa_address" {\n  description = "Network address of the Private Services Access range (with psa_prefix_length), from the platform IPAM; null lets Google choose the range"\n  type        = string\n  default     = null\n  validation {\n    condition     = var.psa_address == null || can(cidrhost("${var.psa_address}/32", 0))\n    error_message = "psa_address must be an IPv4 network address (the platform IPAM range), or null."\n  }\n}\n\nvariable "enable_nat" {\n  description = "Whether to provision regional Cloud Routers and Cloud NAT gateways for outbound internet egress ($0 idle cost when false)"\n  type        = bool\n  default     = false\n}\n\nvariable "enable_flow_logs" {\n  description = "Whether to enable VPC Flow Logs on created subnetworks"\n  type        = bool\n  default     = false\n}\n'}, 'workflows': {'main.tf': '# ==============================================================================\n# STACKVEND: GOOGLE CLOUD WORKFLOWS ORCHESTRATION MODULE\n# ==============================================================================\n\n# ------------------------------------------------------------------------------\n# 1. Main Multi-Agent Orchestrator Workflow\n# ------------------------------------------------------------------------------\nresource "google_workflows_workflow" "main_orchestrator" {\n  project         = var.project_id\n  region          = var.region\n  name            = "castor-main-orchestrator"\n  description     = "Master multi-agent orchestration state machine coordinating Architect, Developer, DevOps, QA, and Release agents"\n  service_account = var.orchestrator_service_account_email\n\n  source_contents = file("${path.module}/../../../workflows/main_orchestrator.yaml")\n\n  labels = {\n    environment = var.environment\n    managed_by  = "castor-terraform"\n  }\n}\n\n# ------------------------------------------------------------------------------\n# 2. SRE Incident Remediation Workflow\n# ------------------------------------------------------------------------------\nresource "google_workflows_workflow" "sre_remediation" {\n  project         = var.project_id\n  region          = var.region\n  name            = "castor-sre-remediation"\n  description     = "Automated incident RCA, ticket creation, and self-healing dispatch workflow"\n  service_account = var.sre_service_account_email\n\n  source_contents = file("${path.module}/../../../workflows/sre_remediation.yaml")\n\n  labels = {\n    environment = var.environment\n    managed_by  = "castor-terraform"\n  }\n}\n\n# ------------------------------------------------------------------------------\n# 3. Workflows IAM Permissions to Invoke Cloud Run (Pub/Sub publish: topic-level, infra/platform)\n# ------------------------------------------------------------------------------\nresource "google_project_iam_member" "orchestrator_run_invoker" {\n  project = var.project_id\n  role    = "roles/run.invoker"\n  member  = "serviceAccount:${var.orchestrator_service_account_email}"\n}\n\n# FD-4AS-c (owner 10-20): no project-level roles/pubsub.publisher here any more. The orchestrator workflow publishes\n# only to the dead-letter topic and the SRE workflow only to spec-intake-events; both hold topic-level grants in\n# infra/platform/pubsub_publishers.tf.\n\nresource "google_project_iam_member" "orchestrator_log_writer" {\n  project = var.project_id\n  role    = "roles/logging.logWriter"\n  member  = "serviceAccount:${var.orchestrator_service_account_email}"\n}\n\nresource "google_project_iam_member" "sre_run_invoker" {\n  project = var.project_id\n  role    = "roles/run.invoker"\n  member  = "serviceAccount:${var.sre_service_account_email}"\n}\n\nresource "google_project_iam_member" "sre_workflow_invoker" {\n  project = var.project_id\n  role    = "roles/workflows.invoker"\n  member  = "serviceAccount:${var.sre_service_account_email}"\n}\n', 'outputs.tf': 'output "main_orchestrator_id" {\n  description = "The unique ID of the Main Orchestrator Workflow."\n  value       = google_workflows_workflow.main_orchestrator.id\n}\n\noutput "main_orchestrator_name" {\n  description = "The resource name of the Main Orchestrator Workflow."\n  value       = google_workflows_workflow.main_orchestrator.name\n}\n\noutput "sre_remediation_id" {\n  description = "The unique ID of the SRE Incident Remediation Workflow."\n  value       = google_workflows_workflow.sre_remediation.id\n}\n\noutput "sre_remediation_name" {\n  description = "The resource name of the SRE Incident Remediation Workflow."\n  value       = google_workflows_workflow.sre_remediation.name\n}\n', 'variables.tf': 'variable "project_id" {\n  description = "The Google Cloud Project ID."\n  type        = string\n}\n\nvariable "region" {\n  description = "The Google Cloud region for deploying workflows."\n  type        = string\n  default     = "us-central1"\n}\n\nvariable "environment" {\n  description = "The deployment environment tier (e.g. prod, staging, dev)."\n  type        = string\n  default     = "prod"\n}\n\nvariable "orchestrator_service_account_email" {\n  description = "The IAM Service Account email used by the Main Orchestrator Workflow."\n  type        = string\n}\n\nvariable "sre_service_account_email" {\n  description = "The IAM Service Account email used by the SRE Incident Remediation Workflow."\n  type        = string\n}\n\nvariable "service_urls" {\n  description = "Map of Cloud Run service names to their live HTTPS URLs."\n  type        = map(string)\n}\n\nvariable "pubsub_topics" {\n  description = "Map of provisioned Pub/Sub topic IDs."\n  type        = map(string)\n}\n'}, 'database-alloydb': {'main.tf': '# ==============================================================================\n# STACKVEND: PARAMETERIZED MODULE - ALLOYDB FOR POSTGRESQL (TIER 2 STATEFUL)\n# ==============================================================================\n# Provisions an enterprise AlloyDB cluster and primary instance with VPC peering,\n# automated backups, and CPU sizing controls.\n# ==============================================================================\n# TI-5-R2 P3 (owner 10-25, as database-cloudsql since FD-4AX): the initial user\'s\n# password (generated unless the caller supplies initial_user_password) is stored\n# in Secret Manager (output secret_id_password); it is never a module output.\n\nlocals {\n  cluster_id  = var.cluster_id != "" ? var.cluster_id : "alloydb-${replace(lower(var.product_id), "_", "-")}"\n  instance_id = var.instance_id != "" ? var.instance_id : "${local.cluster_id}-primary"\n\n  initial_user_password = var.initial_user_password != null ? var.initial_user_password : random_password.alloydb_password[0].result\n\n  default_labels = {\n    managed_by = "castor-terraform"\n    product_id = var.product_id\n  }\n}\n\nresource "random_password" "alloydb_password" {\n  count   = var.initial_user_password == null ? 1 : 0\n  length  = 24\n  special = false\n}\n\nresource "google_alloydb_cluster" "cluster" {\n  project    = var.project_id\n  location   = var.region\n  cluster_id = local.cluster_id\n\n  # FD-4AZ-b1: the top-level `network` argument was removed in google 6.0; it now lives in network_config.\n  network_config {\n    network = var.network\n  }\n\n  initial_user {\n    password = local.initial_user_password\n  }\n\n  automated_backup_policy {\n    enabled = true\n    weekly_schedule {\n      days_of_week = ["MONDAY", "WEDNESDAY", "FRIDAY"]\n      start_times {\n        hours   = 2\n        minutes = 0\n      }\n    }\n  }\n\n  dynamic "encryption_config" {\n    for_each = var.kms_key_name != null ? [1] : []\n    content {\n      kms_key_name = var.kms_key_name\n    }\n  }\n\n  labels = merge(local.default_labels, var.labels)\n\n  # FD-CSQL (F6): the old default was the bare name "default", which the API does not accept and which has no\n  # Private Services Access in a vended project. Refuse a missing network at plan time with a plain message.\n  lifecycle {\n    precondition {\n      condition     = var.network != null\n      error_message = "database-alloydb: set network to a VPC network ID with Private Services Access (e.g. module.network.network_id from networking-vpc)."\n    }\n  }\n}\n\nresource "google_alloydb_instance" "primary" {\n  cluster       = google_alloydb_cluster.cluster.name\n  instance_id   = local.instance_id\n  instance_type = "PRIMARY"\n\n  machine_config {\n    cpu_count = var.cpu_count\n  }\n\n  labels = merge(local.default_labels, var.labels)\n}\n\n# The initial user\'s password, for the workload to read at runtime (AlloyDB\'s initial user is `postgres`).\nresource "google_secret_manager_secret" "initial_user_password" {\n  project   = var.project_id\n  secret_id = "${local.cluster_id}-db-password"\n\n  replication {\n    auto {}\n  }\n}\n\nresource "google_secret_manager_secret_version" "initial_user_password" {\n  secret      = google_secret_manager_secret.initial_user_password.id\n  secret_data = local.initial_user_password\n}\n\n# Opt-in read access for the workload runtime SA. A plain bool keeps count known at plan time even when\n# workload_sa_email is computed by another module.\nresource "google_secret_manager_secret_iam_member" "workload_accessor" {\n  count     = var.grant_workload_secret_access ? 1 : 0\n  project   = var.project_id\n  secret_id = google_secret_manager_secret.initial_user_password.secret_id\n  role      = "roles/secretmanager.secretAccessor"\n  member    = "serviceAccount:${var.workload_sa_email}"\n\n  lifecycle {\n    precondition {\n      condition     = var.workload_sa_email != ""\n      error_message = "grant_workload_secret_access = true requires workload_sa_email."\n    }\n  }\n}\n', 'outputs.tf': 'output "cluster_id" {\n  description = "The ID of the AlloyDB cluster."\n  value       = google_alloydb_cluster.cluster.cluster_id\n}\n\noutput "cluster_name" {\n  description = "The resource name of the AlloyDB cluster."\n  value       = google_alloydb_cluster.cluster.name\n}\n\noutput "instance_id" {\n  description = "The ID of the primary AlloyDB instance."\n  value       = google_alloydb_instance.primary.instance_id\n}\n\noutput "ip_address" {\n  description = "The private IP address of the primary AlloyDB instance."\n  value       = google_alloydb_instance.primary.ip_address\n}\n\noutput "secret_id_password" {\n  description = "Secret Manager secret_id holding the initial user\'s (postgres) password (read it at runtime; the password itself is never an output)"\n  value       = google_secret_manager_secret.initial_user_password.secret_id\n}\n', 'variables.tf': 'variable "project_id" {\n  description = "The GCP project ID to deploy AlloyDB in."\n  type        = string\n}\n\nvariable "region" {\n  description = "The GCP region to host the AlloyDB cluster."\n  type        = string\n  default     = "us-central1"\n}\n\nvariable "product_id" {\n  description = "StackVend product/workload identifier for labeling and naming defaults."\n  type        = string\n  default     = ""\n}\n\nvariable "cluster_id" {\n  description = "The unique identifier of the AlloyDB cluster. If empty, derived from product_id."\n  type        = string\n  default     = ""\n}\n\nvariable "instance_id" {\n  description = "The unique identifier of the primary AlloyDB instance. If empty, derived from cluster_id."\n  type        = string\n  default     = ""\n}\n\nvariable "network" {\n  description = "VPC network ID (projects/PROJECT/global/networks/NAME, e.g. networking-vpc\'s network_id) with an active Private Services Access connection; depend on that module. Required: a bare network name is not accepted."\n  type        = string\n  default     = null\n\n  validation {\n    condition     = var.network == null || can(regex("(^|/)projects/[^/]+/global/networks/[^/]+$", var.network))\n    error_message = "network must be a VPC network ID (projects/PROJECT/global/networks/NAME), not a bare name."\n  }\n}\n\nvariable "initial_user_password" {\n  description = "Initial password for the cluster\'s initial user (postgres). If null, a random password is generated. Either way it is stored in Secret Manager (output secret_id_password)."\n  type        = string\n  sensitive   = true\n  default     = null\n}\n\nvariable "cpu_count" {\n  description = "Number of vCPUs allocated to the primary instance (2, 4, 8, 16, etc.). Default 2."\n  type        = number\n  default     = 2\n}\n\nvariable "kms_key_name" {\n  description = "Optional Cloud KMS CryptoKey resource name for CMEK encryption."\n  type        = string\n  default     = null\n}\n\nvariable "labels" {\n  description = "Key-value labels to attach to the AlloyDB resources."\n  type        = map(string)\n  default     = {}\n}\n\nvariable "workload_sa_email" {\n  description = "Workload runtime service account email that grant_workload_secret_access gives read access to the password secret"\n  type        = string\n  default     = ""\n}\n\nvariable "grant_workload_secret_access" {\n  description = "Grant workload_sa_email roles/secretmanager.secretAccessor on the password secret (requires workload_sa_email)"\n  type        = bool\n  default     = false\n}\n'}, 'event-trigger': {'main.tf': 'terraform {\n  required_version = ">= 1.5.0"\n  required_providers {\n    google = {\n      source = "hashicorp/google"\n    }\n  }\n}\n\nresource "google_eventarc_trigger" "trigger" {\n  project  = var.project_id\n  location = var.region\n  name     = "${var.project_id}-${var.trigger_name_suffix}"\n\n  matching_criteria {\n    attribute = "type"\n    value     = var.event_type\n  }\n\n  destination {\n    cloud_run_service {\n      service = var.destination_run_service_name\n      region  = var.region\n    }\n  }\n\n  service_account = var.service_account_email\n}\n', 'outputs.tf': 'output "trigger_name" {\n  description = "Name of the Eventarc trigger"\n  value       = google_eventarc_trigger.trigger.name\n}\n\noutput "trigger_id" {\n  description = "Resource ID of the Eventarc trigger"\n  value       = google_eventarc_trigger.trigger.id\n}\n', 'variables.tf': 'variable "project_id" {\n  description = "GCP Project ID"\n  type        = string\n}\n\nvariable "region" {\n  description = "GCP Region"\n  type        = string\n  default     = "us-central1"\n}\n\nvariable "trigger_name_suffix" {\n  description = "Suffix for the Eventarc trigger name"\n  type        = string\n  default     = "gcs-trigger"\n}\n\nvariable "event_type" {\n  description = "Event type to match (e.g. \'google.cloud.storage.object.v1.finalized\')"\n  type        = string\n  default     = "google.cloud.storage.object.v1.finalized"\n}\n\nvariable "destination_run_service_name" {\n  description = "Target Cloud Run service name"\n  type        = string\n}\n\nvariable "service_account_email" {\n  description = "Service account email authorized to invoke the destination Cloud Run service"\n  type        = string\n}\n'}, 'storage-bucket': {'main.tf': 'terraform {\n  required_version = ">= 1.5.0"\n  required_providers {\n    google = {\n      source = "hashicorp/google"\n    }\n  }\n}\n\nresource "google_storage_bucket" "bucket" {\n  project                     = var.project_id\n  name                        = "${var.project_id}-${var.bucket_name_suffix}"\n  location                    = var.region\n  uniform_bucket_level_access = var.uniform_bucket_level_access\n  force_destroy               = !var.prevent_destroy\n\n  versioning {\n    enabled = var.versioning_enabled\n  }\n\n  # Lane 14 PR-0b: default CMEK for regulated profiles (no block = Google-managed encryption).\n  dynamic "encryption" {\n    for_each = var.kms_key_name != null ? [1] : []\n    content {\n      default_kms_key_name = var.kms_key_name\n    }\n  }\n\n  dynamic "lifecycle_rule" {\n    for_each = var.lifecycle_delete_age_days > 0 ? [1] : []\n    content {\n      action {\n        type = "Delete"\n      }\n      condition {\n        age = var.lifecycle_delete_age_days\n      }\n    }\n  }\n}\n\nresource "google_storage_bucket_iam_member" "workload_admin" {\n  count  = var.workload_sa_email != "" ? 1 : 0\n  bucket = google_storage_bucket.bucket.name\n  role   = "roles/storage.objectAdmin"\n  member = "serviceAccount:${var.workload_sa_email}"\n}\n', 'outputs.tf': 'output "bucket_name" {\n  description = "Name of the created GCS bucket"\n  value       = google_storage_bucket.bucket.name\n}\n\noutput "bucket_url" {\n  description = "URL of the created GCS bucket"\n  value       = google_storage_bucket.bucket.url\n}\n', 'variables.tf': 'variable "project_id" {\n  description = "GCP Project ID"\n  type        = string\n}\n\nvariable "region" {\n  description = "GCP Region"\n  type        = string\n  default     = "us-central1"\n}\n\nvariable "bucket_name_suffix" {\n  description = "Suffix for the bucket name (e.g. \'uploads\', \'assets\')"\n  type        = string\n  default     = "data"\n}\n\nvariable "versioning_enabled" {\n  description = "Enable object versioning"\n  type        = bool\n  default     = false\n}\n\nvariable "uniform_bucket_level_access" {\n  description = "Enforce uniform bucket-level access (Org Policy compliant)"\n  type        = bool\n  default     = true\n}\n\nvariable "lifecycle_delete_age_days" {\n  description = "Number of days before objects are automatically deleted (0 to disable)"\n  type        = number\n  default     = 0\n}\n\nvariable "prevent_destroy" {\n  description = "When true (FD-4AZ default), force_destroy is off: OpenTofu cannot delete the bucket while it still holds objects. Set false explicitly only for an ephemeral bucket."\n  type        = bool\n  default     = true\n}\n\nvariable "workload_sa_email" {\n  description = "Runtime service account email to grant storage.objectAdmin"\n  type        = string\n  default     = ""\n}\n\nvariable "kms_key_name" {\n  description = "Cloud KMS CryptoKey resource name for the bucket\'s default customer-managed encryption (CMEK), in the bucket\'s location. The Cloud Storage service agent needs roles/cloudkms.cryptoKeyEncrypterDecrypter on it. null = Google-managed encryption."\n  type        = string\n  default     = null\n}\n'}, 'messaging-pubsub': {'main.tf': 'terraform {\n  required_version = ">= 1.5.0"\n  required_providers {\n    google = {\n      source = "hashicorp/google"\n    }\n  }\n}\n\nresource "google_pubsub_topic" "topic" {\n  project      = var.project_id\n  name         = "${var.project_id}-${var.topic_name_suffix}"\n  kms_key_name = var.kms_key_name # lane 14 PR-0b: CMEK for regulated profiles (null = Google-managed)\n}\n\nresource "google_pubsub_topic" "dead_letter" {\n  count        = var.enable_dead_letter ? 1 : 0\n  project      = var.project_id\n  name         = "${var.project_id}-${var.topic_name_suffix}-dlq"\n  kms_key_name = var.kms_key_name\n}\n\nresource "google_pubsub_subscription" "subscription" {\n  count                      = var.enable_subscription ? 1 : 0\n  project                    = var.project_id\n  name                       = "${google_pubsub_topic.topic.name}-sub"\n  topic                      = google_pubsub_topic.topic.name\n  ack_deadline_seconds       = var.ack_deadline_seconds\n  message_retention_duration = var.message_retention_duration\n\n  # StackVend WORKLOAD-SUB-NO-EXPIRY (owner 10-28): never expire from inactivity. Pub/Sub\'s default deletes a\n  # subscription after 31 days without activity (as SUB-NO-EXPIRY fixed for the platform\'s own subscriptions).\n  expiration_policy {\n    ttl = ""\n  }\n\n  dynamic "dead_letter_policy" {\n    for_each = var.enable_dead_letter ? [1] : []\n    content {\n      dead_letter_topic     = google_pubsub_topic.dead_letter[0].id\n      max_delivery_attempts = 5\n    }\n  }\n\n  # StackVend PUSH-SUB-RENDER (owner 10-28): with `push` set (platform-rendered from the typed intent, never an AI\n  # string) the subscription pushes to the workload\'s own Cloud Run service with an OIDC token; null = pull, unchanged.\n  dynamic "push_config" {\n    for_each = var.push == null ? [] : [var.push]\n    content {\n      push_endpoint = push_config.value.endpoint\n      oidc_token {\n        service_account_email = push_config.value.service_account_email\n        audience              = push_config.value.audience\n      }\n    }\n  }\n}\n\nresource "google_pubsub_topic_iam_member" "publisher" {\n  count   = var.workload_sa_email != "" ? 1 : 0\n  project = var.project_id\n  topic   = google_pubsub_topic.topic.name\n  role    = "roles/pubsub.publisher"\n  member  = "serviceAccount:${var.workload_sa_email}"\n}\n\nresource "google_pubsub_subscription_iam_member" "subscriber" {\n  count        = var.enable_subscription && var.workload_sa_email != "" ? 1 : 0\n  project      = var.project_id\n  subscription = google_pubsub_subscription.subscription[0].name\n  role         = "roles/pubsub.subscriber"\n  member       = "serviceAccount:${var.workload_sa_email}"\n}\n', 'outputs.tf': 'output "topic_name" {\n  description = "Name of the Pub/Sub topic"\n  value       = google_pubsub_topic.topic.name\n}\n\noutput "topic_id" {\n  description = "Resource ID of the Pub/Sub topic"\n  value       = google_pubsub_topic.topic.id\n}\n\noutput "subscription_name" {\n  description = "Name of the subscription (if enabled)"\n  value       = var.enable_subscription ? google_pubsub_subscription.subscription[0].name : ""\n}\n\noutput "subscription_id" {\n  description = "Resource ID of the subscription (if enabled)"\n  value       = var.enable_subscription ? google_pubsub_subscription.subscription[0].id : ""\n}\n\noutput "dead_letter_topic_id" {\n  description = "Resource ID of the Dead Letter topic (if enabled)"\n  value       = var.enable_dead_letter ? google_pubsub_topic.dead_letter[0].id : ""\n}\n', 'variables.tf': 'variable "project_id" {\n  description = "GCP Project ID"\n  type        = string\n}\n\nvariable "topic_name_suffix" {\n  description = "Suffix for the Pub/Sub topic name (e.g. \'events\', \'audit\')"\n  type        = string\n  default     = "events"\n}\n\nvariable "enable_subscription" {\n  description = "Whether to create a pull subscription on this topic"\n  type        = bool\n  default     = true\n}\n\nvariable "enable_dead_letter" {\n  description = "Whether to create a Dead Letter Queue (DLQ) topic for failed messages"\n  type        = bool\n  default     = false\n}\n\nvariable "ack_deadline_seconds" {\n  description = "Subscription acknowledge deadline in seconds"\n  type        = number\n  default     = 20\n}\n\nvariable "message_retention_duration" {\n  description = "Message retention duration (e.g. \'604800s\' for 7 days)"\n  type        = string\n  default     = "604800s"\n}\n\nvariable "workload_sa_email" {\n  description = "Workload service account email to grant publisher/subscriber IAM"\n  type        = string\n  default     = ""\n}\n\nvariable "kms_key_name" {\n  description = "Cloud KMS CryptoKey resource name (CMEK) for the topic and its dead-letter topic. The Pub/Sub service agent needs roles/cloudkms.cryptoKeyEncrypterDecrypter on it. null = Google-managed encryption."\n  type        = string\n  default     = null\n}\n\nvariable "push" {\n  description = "PUSH-SUB-RENDER: push delivery for the subscription, rendered by the platform from the typed intent: the endpoint (the workload\'s own Cloud Run service URL plus a path), the service account that signs the OIDC token and the token audience (the service URL). null = pull subscription."\n  type = object({\n    endpoint              = string\n    service_account_email = string\n    audience              = string\n  })\n  default = null\n\n  validation {\n    condition     = var.push == null ? true : (startswith(var.push.endpoint, "https:") && var.push.service_account_email != "" && !startswith(var.push.service_account_email, "serviceAccount:"))\n    error_message = "push.endpoint must be an https URL and push.service_account_email a bare service account email."\n  }\n}\n'}, 'security-secret': {'main.tf': 'terraform {\n  required_version = ">= 1.5.0"\n  required_providers {\n    google = {\n      source = "hashicorp/google"\n    }\n    random = {\n      source = "hashicorp/random"\n    }\n  }\n}\n\nresource "google_secret_manager_secret" "secret" {\n  project   = var.project_id\n  secret_id = var.secret_id\n\n  replication {\n    auto {}\n  }\n}\n\nresource "google_secret_manager_secret_version" "version" {\n  count       = var.secret_data != "" ? 1 : 0\n  secret      = google_secret_manager_secret.secret.id\n  secret_data = var.secret_data\n}\n\n# SECRET-INITIAL-VERSION (owner 11-10): a random first version for a value the workload itself makes and uses (a\n# signing, HMAC or encryption key). Typed infrastructure sets generate_initial_version for a secret the architect\'s\n# plan marks initial_value = "random" only when the workload repository does not hold that secret yet, and keeps it\n# set once it was set; it never adds a version to a secret that already existed.\n# - No keepers: the value is generated once and never changes on later applies.\n# - ignore_changes = [secret_data]: even if random_password were ever replaced (state loss, a future length change),\n#   the version is not replaced, so the key the app has used never rotates by accident.\n# - deletion_policy = "ABANDON": removing it from the configuration leaves the version (and the key) in Secret\n#   Manager instead of destroying it. Deleting the secret itself (or the project) still deletes every version.\n# - The value is stored in the OpenTofu state (no write-only attributes on OpenTofu 1.9); it is never a module output.\nresource "random_password" "initial" {\n  count   = var.generate_initial_version ? 1 : 0\n  length  = 64\n  special = false\n}\n\nresource "google_secret_manager_secret_version" "generated" {\n  count           = var.generate_initial_version ? 1 : 0\n  secret          = google_secret_manager_secret.secret.id\n  secret_data     = random_password.initial[0].result\n  deletion_policy = "ABANDON"\n\n  lifecycle {\n    ignore_changes = [secret_data]\n  }\n}\n\nresource "google_secret_manager_secret_iam_member" "accessor" {\n  count     = var.workload_sa_email != "" ? 1 : 0\n  project   = var.project_id\n  secret_id = google_secret_manager_secret.secret.secret_id\n  role      = "roles/secretmanager.secretAccessor"\n  member    = "serviceAccount:${var.workload_sa_email}"\n}\n', 'outputs.tf': 'output "secret_id" {\n  description = "Identifier of the secret"\n  value       = google_secret_manager_secret.secret.secret_id\n}\n\noutput "secret_name" {\n  description = "Fully qualified resource name of the secret"\n  value       = google_secret_manager_secret.secret.name\n}\n\noutput "secret_version_id" {\n  description = "Resource ID of the created version (if initial data was provided)"\n  # FD-4CC: test the version\'s count, not the sensitive var.secret_data (the same value: count = 1 exactly when\n  # secret_data != ""), so the id never takes the input\'s sensitive mark and the module also validates as a root.\n  value = length(google_secret_manager_secret_version.version) > 0 ? google_secret_manager_secret_version.version[0].id : ""\n}\n', 'variables.tf': 'variable "project_id" {\n  description = "GCP Project ID"\n  type        = string\n}\n\nvariable "secret_id" {\n  description = "Secret identifier (e.g. \'stripe_api_key\', \'db_password\')"\n  type        = string\n}\n\nvariable "secret_data" {\n  description = "Initial secret payload value (optional, can be populated out-of-band)"\n  type        = string\n  default     = ""\n  sensitive   = true\n}\n\nvariable "workload_sa_email" {\n  description = "Runtime service account email to grant secretAccessor role"\n  type        = string\n  default     = ""\n}\n\nvariable "generate_initial_version" {\n  description = "Create one random first version (64 letters and digits) for a value the workload itself makes and uses. Set by the platform on typed infrastructure; stable across applies"\n  type        = bool\n  default     = false\n}\n'}, 'workload-foundation/base': {'apis.tf': '# ==============================================================================\n# STACKVEND: WORKLOAD FOUNDATION - BASE MODULE (APIS)\n# ==============================================================================\n# Declarative enablement of core GCP APIs required by all StackVend workloads.\n# Supports dynamic extension via var.additional_apis for custom services.\n# ==============================================================================\n\nresource "google_project_service" "apis" {\n  project            = var.project_id\n  for_each           = toset(concat(var.base_apis, var.additional_apis))\n  service            = each.key\n  disable_on_destroy = false\n}\n', 'database.tf': '# ==============================================================================\n# STACKVEND: WORKLOAD FOUNDATION - FIRESTORE DATABASE\n# ==============================================================================\n# Provisions Google Cloud Firestore in Native mode with automated teardown safety.\n# ==============================================================================\n\nresource "google_firestore_database" "database" {\n  project                  = var.project_id\n  name                     = "(default)"\n  location_id              = var.region\n  type                     = "FIRESTORE_NATIVE"\n  delete_protection_state  = var.firestore_delete_protection ? "DELETE_PROTECTION_ENABLED" : "DELETE_PROTECTION_DISABLED"\n  deletion_policy          = "DELETE"\n  depends_on               = [google_project_service.apis]\n\n  # Lane 14 PR-0b: CMEK for regulated profiles (no block = Google-managed encryption). Set at creation only.\n  dynamic "cmek_config" {\n    for_each = var.kms_key_name != null ? [1] : []\n    content {\n      kms_key_name = var.kms_key_name\n    }\n  }\n}\n', 'iam.tf': '# ==============================================================================\n# STACKVEND: WORKLOAD FOUNDATION - IAM & SERVICE ACCOUNTS\n# ==============================================================================\n# IAM for the GitHub Actions deployer (sa-gh-deployer) and the workload\'s runtime\n# execution identity (workload_sa).\n#\n# FD-4AT: the deployer holds only what the generated CI workflows run\n# (.github/workflows/deploy-<svc>.yml): `gcloud run deploy --source` and\n# `gcloud run jobs deploy --source` (roles/run.sourceDeveloper: Cloud Run,\n# Cloud Build, the gcloud-managed source repository and bucket), and\n# `gcloud container clusters get-credentials` + `kubectl apply` for GKE\n# Autopilot. No Editor role and no project-wide admin or\n# iam.serviceAccountUser: it may act only as the runtime SA and the Cloud Build\n# (Compute Engine default) SA (section 3).\n# Invoker (public/private) IAM on services stays with Terraform.\n#\n# Known limits: roles/run.sourceDeveloper also carries Pub/Sub topic and\n# subscription create/delete and Eventarc admin (Google\'s predefined role for\n# source deploys). roles/container.developer has no Kubernetes RBAC create\n# (Role/RoleBinding/ClusterRole/ClusterRoleBinding), so a k8s/ manifest set\n# that carries RBAC objects fails at `kubectl apply`; no generator emits them.\n# ==============================================================================\n\n# ------------------------------------------------------------------------------\n# 1. CI/CD Deployer Service Account Roles\n# ------------------------------------------------------------------------------\n# GHA-DEPLOY-SWITCH: every deployer grant exists only while the switch is on (local.github_actions_deploy_count,\n# wif.tf); the moved blocks keep the existing single instance as [0] (no change with the switch on).\nmoved {\n  from = google_project_iam_member.deployer_run_source_developer\n  to   = google_project_iam_member.deployer_run_source_developer[0]\n}\n\nmoved {\n  from = google_project_iam_member.deployer_logging_viewer\n  to   = google_project_iam_member.deployer_logging_viewer[0]\n}\n\nmoved {\n  from = google_project_iam_member.deployer_container_developer\n  to   = google_project_iam_member.deployer_container_developer[0]\n}\n\nmoved {\n  from = google_service_account_iam_member.deployer_runtime_sa_user\n  to   = google_service_account_iam_member.deployer_runtime_sa_user[0]\n}\n\nmoved {\n  from = google_service_account_iam_member.deployer_build_sa_user\n  to   = google_service_account_iam_member.deployer_build_sa_user[0]\n}\n\n# Deploy from source: Cloud Run services/jobs, the source build, the\n# gcloud-managed `cloud-run-source-deploy` repository and source bucket.\nresource "google_project_iam_member" "deployer_run_source_developer" {\n  count   = local.github_actions_deploy_count\n  project = var.project_id\n  role    = "roles/run.sourceDeveloper"\n  member  = "serviceAccount:${google_service_account.github_deployer[0].email}"\n}\n\n# Read Cloud Build logs while gcloud waits for the source build.\nresource "google_project_iam_member" "deployer_logging_viewer" {\n  count   = local.github_actions_deploy_count\n  project = var.project_id\n  role    = "roles/logging.viewer"\n  member  = "serviceAccount:${google_service_account.github_deployer[0].email}"\n}\n\n# GKE Autopilot archetype: clusters describe / get-credentials + `kubectl apply -f k8s/`.\nresource "google_project_iam_member" "deployer_container_developer" {\n  count   = local.github_actions_deploy_count\n  project = var.project_id\n  role    = "roles/container.developer"\n  member  = "serviceAccount:${google_service_account.github_deployer[0].email}"\n}\n\n# ------------------------------------------------------------------------------\n# 2. Workload Runtime Service Account & Scoped Permissions\n# ------------------------------------------------------------------------------\n# SA-ACCOUNT-ID-TRIM: trailing dashes of the 20-character cut are dropped (an account_id cannot end in \'-\'); a cut\n# that does not end in \'-\' is unchanged.\nresource "google_service_account" "workload_sa" {\n  project      = var.project_id\n  account_id   = "sa-${replace(substr(replace(var.product_id, "_", "-"), 0, 20), "/-+$/", "")}"\n  display_name = "Runtime Service Account for ${var.product_id}"\n}\n\nresource "google_project_iam_member" "workload_datastore_user" {\n  project = var.project_id\n  role    = "roles/datastore.user"\n  member  = "serviceAccount:${google_service_account.workload_sa.email}"\n}\n\nresource "google_project_iam_member" "workload_log_writer" {\n  project = var.project_id\n  role    = "roles/logging.logWriter"\n  member  = "serviceAccount:${google_service_account.workload_sa.email}"\n}\n\nresource "google_project_iam_member" "workload_pubsub_publisher" {\n  project = var.project_id\n  role    = "roles/pubsub.publisher"\n  member  = "serviceAccount:${google_service_account.workload_sa.email}"\n}\n\nresource "google_project_iam_member" "workload_storage_user" {\n  project = var.project_id\n  role    = "roles/storage.objectUser"\n  member  = "serviceAccount:${google_service_account.workload_sa.email}"\n}\n\n# ------------------------------------------------------------------------------\n# 3. The deployer may act only as the runtime SA and the Cloud Build SA\n# ------------------------------------------------------------------------------\n# `--service-account` on `gcloud run deploy` / `gcloud run jobs deploy`.\nresource "google_service_account_iam_member" "deployer_runtime_sa_user" {\n  count              = local.github_actions_deploy_count\n  service_account_id = google_service_account.workload_sa.name\n  role               = "roles/iam.serviceAccountUser"\n  member             = "serviceAccount:${google_service_account.github_deployer[0].email}"\n}\n\n# `--source` submits a Cloud Build that runs as the project\'s default build SA\n# (the Compute Engine default SA in child projects). FD-7L 2b (review F1): the project number is read from the\n# project itself (a data source, known at plan time), so this grant\'s service_account_id is a known string that the\n# platform\'s identity content policy checks before the apply. It used to come from the WIF pool\'s resource name\n# (projects/<project_number>/...), which is unknown until the pool exists; the value is the same.\ndata "google_project" "this" {\n  count      = local.github_actions_deploy_count\n  project_id = var.project_id\n}\n\nresource "google_service_account_iam_member" "deployer_build_sa_user" {\n  count              = local.github_actions_deploy_count\n  service_account_id = "projects/${var.project_id}/serviceAccounts/${data.google_project.this[0].number}-compute@developer.gserviceaccount.com"\n  role               = "roles/iam.serviceAccountUser"\n  member             = "serviceAccount:${google_service_account.github_deployer[0].email}"\n}\n', 'outputs.tf': '# ==============================================================================\n# STACKVEND: WORKLOAD FOUNDATION - BASE MODULE OUTPUTS\n# ==============================================================================\n\noutput "workload_sa_email" {\n  description = "Runtime service account email for the workload"\n  value       = google_service_account.workload_sa.email\n}\n\noutput "workload_sa_id" {\n  description = "Runtime service account ID"\n  value       = google_service_account.workload_sa.id\n}\n\noutput "deployer_sa_email" {\n  description = "CI/CD GitHub Actions deployer service account email (null when enable_github_actions_deploy is false)"\n  value       = one(google_service_account.github_deployer[*].email)\n}\n\noutput "wif_pool_name" {\n  description = "Workload Identity Pool name (null when enable_github_actions_deploy is false)"\n  value       = one(google_iam_workload_identity_pool.github_pool[*].name)\n}\n\noutput "wif_provider_name" {\n  description = "Workload Identity Provider resource name (null when enable_github_actions_deploy is false)"\n  value       = one(google_iam_workload_identity_pool_provider.github_provider[*].name)\n}\n\noutput "docker_repo_id" {\n  description = "Artifact Registry Docker repository ID"\n  value       = google_artifact_registry_repository.docker_repo.repository_id\n}\n\noutput "database_name" {\n  description = "Firestore database name"\n  value       = google_firestore_database.database.name\n}\n', 'registry.tf': '# ==============================================================================\n# STACKVEND: WORKLOAD FOUNDATION - ARTIFACT REGISTRY\n# ==============================================================================\n# Provisions Docker container image repository for workload builds and images.\n# ==============================================================================\n\nresource "google_artifact_registry_repository" "docker_repo" {\n  project       = var.project_id\n  location      = var.region\n  repository_id = replace(var.product_id, "_", "-")\n  description   = "Docker container image repository for ${var.product_id}"\n  format        = "DOCKER"\n  kms_key_name  = var.kms_key_name # lane 14 PR-0b: CMEK for regulated profiles (null = Google-managed)\n  depends_on    = [google_project_service.apis]\n}\n', 'variables.tf': '# ==============================================================================\n# STACKVEND: WORKLOAD FOUNDATION - BASE MODULE VARIABLES\n# ==============================================================================\n\nvariable "project_id" {\n  description = "Target GCP Child Project ID"\n  type        = string\n}\n\nvariable "region" {\n  description = "GCP Region for regional resources"\n  type        = string\n  default     = "us-central1"\n}\n\nvariable "product_id" {\n  description = "Workload Product ID"\n  type        = string\n}\n\nvariable "github_repo_full_name" {\n  description = "Full GitHub repository name in owner/repo form (e.g. example-org/example-workload)"\n  type        = string\n}\n\nvariable "github_repository_id" {\n  description = "FD-4AT-c: GitHub\'s immutable numeric id of github_repo_full_name, resolved by vending and supplied by the platform at apply time (never by generated code). Empty = not pinned; the repository name + main-branch condition still applies."\n  type        = string\n  default     = ""\n\n  validation {\n    condition     = var.github_repository_id == "" || can(regex("^[1-9][0-9]*$", var.github_repository_id))\n    error_message = "github_repository_id must be empty or GitHub\'s numeric repository id (digits only)."\n  }\n}\n\nvariable "enable_github_actions_deploy" {\n  description = "GHA-DEPLOY-SWITCH: the workload\'s GitHub Actions deploy path. true (the default, the module before this input existed) creates the Workload Identity Federation pool and provider, the deployer service account sa-gh-deployer and its roles, so the generated .github/workflows/deploy-<service>.yml can deploy the app. false creates none of them: every deploy goes through the platform\'s pipeline. Supplied by the platform from the workload record."\n  type        = bool\n  default     = true\n  nullable    = false\n}\n\nvariable "github_default_branch" {\n  description = "FD-4CI-b-R1-WIF: the workload\'s recorded default branch, the only branch whose GitHub Actions runs the WIF condition accepts (exact refs/heads/<branch>). Supplied by the platform from the workload record; \\"main\\" = the condition before this input existed."\n  type        = string\n  default     = "main"\n  nullable    = false\n\n  # The platform\'s branch-name grammar (shared/settings.py is_branch_name): 1..100 of letters, digits, \'.\', \'_\', \'-\',\n  # \'/\'; not "HEAD"; no leading \'-\', \'/\' or \'.\'; no trailing \'/\' or \'.\'; no \'..\'; no empty path component; no\n  # component starting with \'.\' or ending in \'.lock\'. Nothing else reaches the condition (no quote, no wildcard).\n  validation {\n    condition     = can(regex("^[A-Za-z0-9._/-]{1,100}$", var.github_default_branch)) && var.github_default_branch != "HEAD"\n    error_message = "github_default_branch must be 1 to 100 letters, digits, \'.\', \'_\', \'-\' or \'/\' and not HEAD."\n  }\n\n  validation {\n    condition     = !can(regex("^[-/.]", var.github_default_branch)) && !can(regex("[/.]$", var.github_default_branch)) && !can(regex("\\\\.\\\\.", var.github_default_branch))\n    error_message = "github_default_branch must not start with \'-\', \'/\' or \'.\', end with \'/\' or \'.\', or contain \'..\'."\n  }\n\n  validation {\n    condition     = !can(regex("//", var.github_default_branch)) && !can(regex("/\\\\.", var.github_default_branch)) && !can(regex("\\\\.lock(/|$)", var.github_default_branch))\n    error_message = "github_default_branch must not have an empty path component, or one that starts with \'.\' or ends in \'.lock\'."\n  }\n}\n\nvariable "base_apis" {\n  description = "Foundational GCP APIs required by all StackVend workloads"\n  type        = list(string)\n  default = [\n    "run.googleapis.com",\n    "firestore.googleapis.com",\n    "cloudbuild.googleapis.com",\n    "artifactregistry.googleapis.com",\n    "cloudresourcemanager.googleapis.com",\n    "iam.googleapis.com",\n    "identitytoolkit.googleapis.com",\n    "iap.googleapis.com",\n    "pubsub.googleapis.com",\n    "storage.googleapis.com",\n  ]\n}\n\nvariable "additional_apis" {\n  description = "Extra GCP APIs requested by custom extensions in custom.tf"\n  type        = list(string)\n  default     = []\n}\n\nvariable "firestore_delete_protection" {\n  description = "Enable delete protection on the workload Firestore database (FD-4AZ: on by default). Set false explicitly only for an ephemeral workload."\n  type        = bool\n  default     = true\n}\n', 'wif.tf': '# ==============================================================================\n# STACKVEND: WORKLOAD FOUNDATION - WORKLOAD IDENTITY FEDERATION (WIF)\n# ==============================================================================\n# Provisions keyless OIDC authentication for GitHub Actions CI/CD workflows.\n# Dynamically binds GitHub repository to the deployer service account.\n# ==============================================================================\n\nlocals {\n  wif_repository_id_clause = var.github_repository_id == "" ? "" : " && assertion.repository_id == \'${var.github_repository_id}\'"\n  # GHA-DEPLOY-SWITCH: one instance of every GitHub Actions deploy resource (pool, provider, deployer SA, its WIF\n  # binding and roles) while the switch is on (default), none when it is off.\n  github_actions_deploy_count = var.enable_github_actions_deploy ? 1 : 0\n}\n\n# GHA-DEPLOY-SWITCH: the resources below and the deployer roles in iam.tf gained `count`. These moved blocks keep the\n# existing single instance as [0], so a workload with the switch on plans no change.\nmoved {\n  from = google_iam_workload_identity_pool.github_pool\n  to   = google_iam_workload_identity_pool.github_pool[0]\n}\n\nmoved {\n  from = google_iam_workload_identity_pool_provider.github_provider\n  to   = google_iam_workload_identity_pool_provider.github_provider[0]\n}\n\nmoved {\n  from = google_service_account.github_deployer\n  to   = google_service_account.github_deployer[0]\n}\n\nmoved {\n  from = google_service_account_iam_member.github_wif_binding\n  to   = google_service_account_iam_member.github_wif_binding[0]\n}\n\nresource "google_iam_workload_identity_pool" "github_pool" {\n  count                     = local.github_actions_deploy_count\n  project                   = var.project_id\n  workload_identity_pool_id = "castor-gh-pool"\n  display_name              = "StackVend GitHub Pool"\n  description               = "Workload Identity Pool for GitHub Actions keyless authentication"\n  disabled                  = false\n  depends_on                = [google_project_service.apis]\n}\n\nresource "google_iam_workload_identity_pool_provider" "github_provider" {\n  count                              = local.github_actions_deploy_count\n  project                            = var.project_id\n  workload_identity_pool_id          = google_iam_workload_identity_pool.github_pool[0].workload_identity_pool_id\n  workload_identity_pool_provider_id = "github-provider"\n  display_name                       = "GitHub Actions Provider"\n  description                        = "OIDC Provider for GitHub Actions"\n  disabled                           = false\n\n  attribute_mapping = {\n    "google.subject"             = "assertion.sub"\n    "attribute.actor"            = "assertion.actor"\n    "attribute.repository"       = "assertion.repository"\n    "attribute.repository_owner" = "assertion.repository_owner"\n    "attribute.repository_id"    = "assertion.repository_id"\n    "attribute.ref"              = "assertion.ref"\n  }\n\n  # FD-4AT: only one branch of this workload repository, and only the events the generated workflows use\n  # (push to that branch, workflow_dispatch), so a pull_request_target / workflow_run / schedule run is rejected.\n  # FD-4AT-c: when the platform supplies the repository\'s immutable numeric id, the token must also carry that\n  # assertion.repository_id, so a deleted-and-re-created repository with the same name is rejected. Without the id\n  # the condition is byte-identical to FD-4AT\'s (no change for workloads vended before FD-4AT-c). Exact equality.\n  # FD-4CI-b-R1-WIF: the one branch is the workload\'s recorded default branch (var.github_default_branch, validated\n  # to the platform\'s branch-name grammar); "main" (the default) renders the FD-4AT ref byte for byte. Still exact.\n  attribute_condition = "assertion.repository == \'${var.github_repo_full_name}\'${local.wif_repository_id_clause} && assertion.ref == \'refs/heads/${var.github_default_branch}\' && assertion.event_name in [\'push\',\'workflow_dispatch\']"\n\n  oidc {\n    issuer_uri = "https://token.actions.githubusercontent.com"\n  }\n}\n\nresource "google_service_account" "github_deployer" {\n  count        = local.github_actions_deploy_count\n  project      = var.project_id\n  account_id   = "sa-gh-deployer"\n  display_name = "GitHub Actions Workload Deployer"\n  depends_on   = [google_project_service.apis]\n}\n\nresource "google_service_account_iam_member" "github_wif_binding" {\n  count              = local.github_actions_deploy_count\n  service_account_id = google_service_account.github_deployer[0].name\n  role               = "roles/iam.workloadIdentityUser"\n  member             = "principalSet://iam.googleapis.com/${google_iam_workload_identity_pool.github_pool[0].name}/attribute.repository/${var.github_repo_full_name}"\n}\n', 'compliance.tf': '# ==============================================================================\n# STACKVEND: WORKLOAD FOUNDATION - REGULATED-PROFILE CONTROLS (LANE 14 PR-0b)\n# ==============================================================================\n# Inputs the platform sets only when the workload\'s stored compliance profile is\n# regulated (HIPAA, FedRAMP, CJIS, PCI-DSS, EU). Their defaults leave a standard\n# workload exactly as before: no CMEK, no project audit configuration.\n# ==============================================================================\n\nvariable "kms_key_name" {\n  description = "Cloud KMS CryptoKey resource name for the Artifact Registry repository and the Firestore database (CMEK). null = Google-managed encryption."\n  type        = string\n  default     = null\n}\n\nvariable "enable_data_access_audit_logs" {\n  description = "Turn on Data Access audit logs (data_access_log_types) for all services of the workload project."\n  type        = bool\n  default     = false\n}\n\nvariable "data_access_log_types" {\n  description = "Data Access audit log types turned on by enable_data_access_audit_logs (ADMIN_READ, DATA_READ, DATA_WRITE)."\n  type        = list(string)\n  default     = ["DATA_READ", "DATA_WRITE"]\n}\n\n# Authoritative for the allServices audit configuration of this (dedicated child) project.\nresource "google_project_iam_audit_config" "data_access" {\n  count   = var.enable_data_access_audit_logs ? 1 : 0\n  project = var.project_id\n  service = "allServices"\n\n  dynamic "audit_log_config" {\n    for_each = toset(var.data_access_log_types)\n    content {\n      log_type = audit_log_config.value\n    }\n  }\n}\n'}, 'cache-redis': {'main.tf': 'terraform {\n  required_version = ">= 1.5.0"\n  required_providers {\n    google = {\n      source = "hashicorp/google"\n    }\n  }\n}\n\nresource "google_redis_instance" "cache" {\n  project                 = var.project_id\n  region                  = var.region\n  name                    = "${var.project_id}-${var.instance_name_suffix}"\n  tier                    = var.tier\n  memory_size_gb          = var.memory_size_gb\n  authorized_network      = var.authorized_network\n  transit_encryption_mode = var.transit_encryption_mode\n  auth_enabled            = var.auth_enabled\n  customer_managed_key    = var.kms_key_name # lane 14 PR-0b: CMEK for regulated profiles (null = Google-managed)\n}\n', 'outputs.tf': 'output "instance_id" {\n  description = "Identifier of the Redis instance"\n  value       = google_redis_instance.cache.id\n}\n\noutput "host" {\n  description = "IP address of the Redis instance"\n  value       = google_redis_instance.cache.host\n}\n\noutput "port" {\n  description = "Port number of the Redis instance"\n  value       = google_redis_instance.cache.port\n}\n\noutput "current_location_id" {\n  description = "The zone where the instance is currently provisioned"\n  value       = google_redis_instance.cache.current_location_id\n}\n', 'variables.tf': 'variable "project_id" {\n  description = "GCP Project ID"\n  type        = string\n}\n\nvariable "region" {\n  description = "GCP Region"\n  type        = string\n  default     = "us-central1"\n}\n\nvariable "instance_name_suffix" {\n  description = "Suffix for the Redis instance name (e.g. \'cache\', \'session\')"\n  type        = string\n  default     = "cache"\n}\n\nvariable "tier" {\n  description = "Service tier (BASIC or STANDARD_HA)"\n  type        = string\n  default     = "BASIC"\n}\n\nvariable "memory_size_gb" {\n  description = "Redis memory size in GiB"\n  type        = number\n  default     = 1\n}\n\nvariable "authorized_network" {\n  description = "VPC Network ID authorized to connect to Redis"\n  type        = string\n  default     = "default"\n}\n\nvariable "transit_encryption_mode" {\n  description = "In-transit encryption mode (SERVER_AUTHENTICATION or DISABLED)"\n  type        = string\n  default     = "SERVER_AUTHENTICATION"\n}\n\nvariable "auth_enabled" {\n  description = "Enable Redis AUTH password authentication"\n  type        = bool\n  default     = true\n}\n\nvariable "kms_key_name" {\n  description = "Cloud KMS CryptoKey resource name (CMEK) for the instance, in the instance\'s region. The Memorystore service agent needs roles/cloudkms.cryptoKeyEncrypterDecrypter on it. null = Google-managed encryption."\n  type        = string\n  default     = null\n}\n'}, 'workflows-dag': {'main.tf': 'terraform {\n  required_version = ">= 1.5.0"\n  required_providers {\n    google = {\n      source = "hashicorp/google"\n    }\n  }\n}\n\nresource "google_workflows_workflow" "workflow" {\n  project         = var.project_id\n  region          = var.region\n  name            = "${var.project_id}-${var.workflow_name_suffix}"\n  description     = "Workload orchestration workflow state machine managed by StackVend"\n  service_account = var.service_account_email\n  source_contents = var.source_contents\n}\n', 'outputs.tf': 'output "workflow_name" {\n  description = "Name of the Cloud Workflows state machine"\n  value       = google_workflows_workflow.workflow.name\n}\n\noutput "workflow_id" {\n  description = "Resource ID of the Cloud Workflows state machine"\n  value       = google_workflows_workflow.workflow.id\n}\n', 'variables.tf': 'variable "project_id" {\n  description = "GCP Project ID"\n  type        = string\n}\n\nvariable "region" {\n  description = "GCP Region"\n  type        = string\n  default     = "us-central1"\n}\n\nvariable "workflow_name_suffix" {\n  description = "Suffix for the workflow resource name"\n  type        = string\n  default     = "pipeline"\n}\n\nvariable "service_account_email" {\n  description = "Service account email that executes the workflow steps"\n  type        = string\n}\n\nvariable "source_contents" {\n  description = "YAML source definition for the workflow state machine"\n  type        = string\n  default     = "main:\\n  steps:\\n    - init:\\n        return: \'ok\'\\n"\n}\n'}, 'orchestration-composer': {'main.tf': '# ==============================================================================\n# STACKVEND: PARAMETERIZED MODULE - CLOUD COMPOSER (TIER 2 STATEFUL)\n# ==============================================================================\n# Provisions a managed Cloud Composer (Apache Airflow) environment with\n# parameterized sizing and maintenance policies.\n# ==============================================================================\n\nlocals {\n  environment_name = var.environment_name != "" ? var.environment_name : "composer-${replace(lower(var.product_id), "_", "-")}"\n\n  default_labels = {\n    managed_by = "castor-terraform"\n    product_id = var.product_id\n  }\n}\n\nresource "google_composer_environment" "environment" {\n  project  = var.project_id\n  region   = var.region\n  name     = local.environment_name\n\n  config {\n    environment_size = var.environment_size\n\n    software_config {\n      image_version = var.image_version\n    }\n\n    node_config {\n      service_account = var.service_account\n    }\n  }\n\n  labels = merge(local.default_labels, var.labels)\n}\n', 'outputs.tf': 'output "environment_id" {\n  description = "The ID of the Cloud Composer environment."\n  value       = google_composer_environment.environment.id\n}\n\noutput "environment_name" {\n  description = "The name of the Cloud Composer environment."\n  value       = google_composer_environment.environment.name\n}\n\noutput "airflow_uri" {\n  description = "The URI of the Apache Airflow Web UI."\n  value       = google_composer_environment.environment.config[0].airflow_uri\n}\n\noutput "gcs_bucket" {\n  description = "The Cloud Storage prefix/bucket used by the environment."\n  value       = google_composer_environment.environment.config[0].dag_gcs_prefix\n}\n', 'variables.tf': 'variable "project_id" {\n  description = "The GCP project ID to deploy Cloud Composer in."\n  type        = string\n}\n\nvariable "region" {\n  description = "The GCP region to host the Cloud Composer environment."\n  type        = string\n  default     = "us-central1"\n}\n\nvariable "product_id" {\n  description = "StackVend product/workload identifier for labeling and naming defaults."\n  type        = string\n  default     = ""\n}\n\nvariable "environment_name" {\n  description = "The name of the Cloud Composer environment. If empty, derived from product_id."\n  type        = string\n  default     = ""\n}\n\nvariable "environment_size" {\n  description = "The size of the Cloud Composer 2 environment: \'ENVIRONMENT_SIZE_SMALL\', \'ENVIRONMENT_SIZE_MEDIUM\', or \'ENVIRONMENT_SIZE_LARGE\'."\n  type        = string\n  default     = "ENVIRONMENT_SIZE_SMALL"\n}\n\nvariable "image_version" {\n  description = "The version of the Airflow image to use. Defaults to null (latest Composer 2 image)."\n  type        = string\n  default     = null\n}\n\nvariable "service_account" {\n  description = "Optional custom service account for Composer workers. If null, uses default compute service account."\n  type        = string\n  default     = null\n}\n\nvariable "labels" {\n  description = "Key-value labels to attach to the Cloud Composer environment."\n  type        = map(string)\n  default     = {}\n}\n'}, 'dns-record': {'main.tf': 'terraform {\n  required_version = ">= 1.5.0"\n  required_providers {\n    google = {\n      source = "hashicorp/google"\n    }\n  }\n}\n\nresource "google_dns_record_set" "record" {\n  project      = var.project_id\n  managed_zone = var.managed_zone\n  name         = var.record_name\n  type         = var.record_type\n  ttl          = var.ttl\n  rrdatas      = var.rrdatas\n}\n', 'outputs.tf': 'output "record_name" {\n  description = "Name of the DNS record"\n  value       = google_dns_record_set.record.name\n}\n\noutput "record_type" {\n  description = "Type of the DNS record"\n  value       = google_dns_record_set.record.type\n}\n', 'variables.tf': 'variable "project_id" {\n  description = "GCP Project ID"\n  type        = string\n}\n\nvariable "managed_zone" {\n  description = "Name of the Google Cloud DNS managed zone"\n  type        = string\n}\n\nvariable "record_name" {\n  description = "Fully qualified domain name (must end with a period, e.g. \'api.example.com.\')"\n  type        = string\n}\n\nvariable "record_type" {\n  description = "DNS record type (A, CNAME, TXT, etc.)"\n  type        = string\n  default     = "CNAME"\n}\n\nvariable "ttl" {\n  description = "Time to live (seconds)"\n  type        = number\n  default     = 300\n}\n\nvariable "rrdatas" {\n  description = "List of resource record data strings"\n  type        = list(string)\n}\n'}, 'database-cloudsql': {'main.tf': 'terraform {\n  required_version = ">= 1.5.0"\n  required_providers {\n    google = {\n      source = "hashicorp/google"\n    }\n    random = {\n      source = "hashicorp/random"\n    }\n  }\n}\n\n# FD-4AX: no default password literal. A per-instance password is generated unless the caller supplies\n# var.db_password, and is stored in Secret Manager (output secret_id_password). It is never a module output.\n# Created unconditionally so that no count depends on the sensitive variable (portable across OpenTofu and Terraform).\nresource "random_password" "db" {\n  length  = 32\n  special = false\n}\n\nlocals {\n  db_password = var.db_password != "" ? var.db_password : random_password.db.result\n}\n\nresource "google_sql_database_instance" "instance" {\n  project             = var.project_id\n  region              = var.region\n  name                = "${var.project_id}-${var.instance_name_suffix}"\n  database_version    = var.database_version\n  deletion_protection = var.deletion_protection\n  encryption_key_name = var.kms_key_name # lane 14 PR-0b: CMEK for regulated profiles (null = Google-managed)\n\n  settings {\n    tier              = var.tier\n    availability_type = "ZONAL"\n    disk_size         = 10\n    disk_type         = "PD_SSD"\n\n    backup_configuration {\n      enabled    = true\n      start_time = "03:00"\n    }\n\n    # FD-4AZ-b1: `require_ssl` was removed in google 6.0. ssl_mode defaults to "ENCRYPTED_ONLY": TLS is still\n    # required; a client certificate is no longer required (the removed require_ssl = true did require one).\n    # FD-CSQL: private IP on var.private_network_id (a VPC with Private Services Access, e.g. networking-vpc\'s\n    # network_id) and a public IPv4 address only when enable_public_ip = true. Cloud SQL refuses an instance with\n    # neither; the precondition below says so at plan time instead of an API 400 at create.\n    ip_configuration {\n      ipv4_enabled    = var.enable_public_ip\n      private_network = var.private_network_id\n      ssl_mode        = var.ssl_mode\n    }\n  }\n\n  lifecycle {\n    precondition {\n      condition     = var.enable_public_ip || var.private_network_id != null\n      error_message = "database-cloudsql: set private_network_id (a VPC network with Private Services Access, e.g. module.network.network_id from networking-vpc) or enable_public_ip = true. Cloud SQL refuses an instance with neither."\n    }\n  }\n}\n\nresource "google_sql_database" "database" {\n  project  = var.project_id\n  instance = google_sql_database_instance.instance.name\n  name     = var.database_name\n}\n\nresource "google_sql_user" "user" {\n  project  = var.project_id\n  instance = google_sql_database_instance.instance.name\n  name     = var.db_user\n  password = local.db_password\n}\n\n# Grant workload service account Cloud SQL Client role for Auth Proxy socket access\nresource "google_project_iam_member" "cloudsql_client" {\n  count   = var.workload_sa_email != "" ? 1 : 0\n  project = var.project_id\n  role    = "roles/cloudsql.client"\n  member  = "serviceAccount:${var.workload_sa_email}"\n}\n\nresource "google_secret_manager_secret" "db_password" {\n  project   = var.project_id\n  secret_id = "${var.project_id}-${var.instance_name_suffix}-db-password"\n\n  replication {\n    auto {}\n  }\n}\n\nresource "google_secret_manager_secret_version" "db_password" {\n  secret      = google_secret_manager_secret.db_password.id\n  secret_data = local.db_password\n}\n\n# Opt-in read access for the workload runtime SA. A plain bool keeps count known at plan time even when\n# workload_sa_email is computed by another module.\nresource "google_secret_manager_secret_iam_member" "workload_accessor" {\n  count     = var.grant_workload_secret_access ? 1 : 0\n  project   = var.project_id\n  secret_id = google_secret_manager_secret.db_password.secret_id\n  role      = "roles/secretmanager.secretAccessor"\n  member    = "serviceAccount:${var.workload_sa_email}"\n\n  lifecycle {\n    precondition {\n      condition     = var.workload_sa_email != ""\n      error_message = "grant_workload_secret_access = true requires workload_sa_email."\n    }\n  }\n}\n', 'outputs.tf': 'output "instance_name" {\n  description = "Name of the Cloud SQL instance"\n  value       = google_sql_database_instance.instance.name\n}\n\noutput "instance_connection_name" {\n  description = "Connection name for Cloud SQL Auth Proxy socket (PROJECT:REGION:INSTANCE)"\n  value       = google_sql_database_instance.instance.connection_name\n}\n\noutput "private_ip_address" {\n  description = "Private IP address of the instance on private_network_id (empty when the instance has no private IP)"\n  value       = google_sql_database_instance.instance.private_ip_address\n}\n\noutput "database_name" {\n  description = "Name of the default logical database"\n  value       = google_sql_database.database.name\n}\n\noutput "db_user" {\n  description = "Name of the database user"\n  value       = google_sql_user.user.name\n}\n\noutput "secret_id_password" {\n  description = "Secret Manager secret_id holding the db_user password (read it at runtime; the password itself is never an output)"\n  value       = google_secret_manager_secret.db_password.secret_id\n}\n', 'variables.tf': 'variable "project_id" {\n  description = "GCP Project ID"\n  type        = string\n}\n\nvariable "region" {\n  description = "GCP Region"\n  type        = string\n  default     = "us-central1"\n}\n\nvariable "instance_name_suffix" {\n  description = "Suffix for the Cloud SQL instance name (e.g. \'db\', \'postgres\')"\n  type        = string\n  default     = "pg-db"\n}\n\nvariable "database_version" {\n  description = "Database engine version (e.g. \'POSTGRES_16\', \'MYSQL_8_0\')"\n  type        = string\n  default     = "POSTGRES_16"\n}\n\nvariable "tier" {\n  description = "Machine tier (e.g. \'db-f1-micro\', \'db-custom-2-7680\')"\n  type        = string\n  default     = "db-f1-micro"\n}\n\nvariable "database_name" {\n  description = "Name of the initial logical database"\n  type        = string\n  default     = "app_db"\n}\n\nvariable "db_user" {\n  description = "Master database username"\n  type        = string\n  default     = "app_user"\n}\n\nvariable "db_password" {\n  description = "Optional caller-supplied password for db_user. If empty, a random 32-character password is generated. Either way it is stored in Secret Manager (output secret_id_password)."\n  type        = string\n  default     = ""\n  sensitive   = true\n}\n\nvariable "deletion_protection" {\n  description = "Block OpenTofu from deleting the Cloud SQL instance (FD-4AZ: on by default). Set false explicitly only for an ephemeral instance you intend to destroy."\n  type        = bool\n  default     = true\n}\n\nvariable "private_network_id" {\n  description = "VPC network ID or self-link (projects/PROJECT/global/networks/NAME) for the instance\'s private IP. The network must already have an active Private Services Access connection (networking-vpc creates one; depend on that module). Null = no private IP."\n  type        = string\n  default     = null\n\n  validation {\n    condition     = var.private_network_id == null || can(regex("(^|/)projects/[^/]+/global/networks/[^/]+$", var.private_network_id))\n    error_message = "private_network_id must be a VPC network ID or self-link (projects/PROJECT/global/networks/NAME), or null."\n  }\n}\n\nvariable "enable_public_ip" {\n  description = "Give the instance a public IPv4 address (off by default). Needed only when private_network_id is not set; connections still require TLS (ssl_mode)."\n  type        = bool\n  default     = false\n}\n\nvariable "ssl_mode" {\n  description = "Cloud SQL connection encryption: ENCRYPTED_ONLY (default: TLS required, no client certificate), TRUSTED_CLIENT_CERTIFICATE_REQUIRED (TLS plus a client certificate signed by the instance CA), or ALLOW_UNENCRYPTED_AND_ENCRYPTED."\n  type        = string\n  default     = "ENCRYPTED_ONLY"\n\n  validation {\n    condition     = contains(["ENCRYPTED_ONLY", "TRUSTED_CLIENT_CERTIFICATE_REQUIRED", "ALLOW_UNENCRYPTED_AND_ENCRYPTED"], var.ssl_mode)\n    error_message = "ssl_mode must be ENCRYPTED_ONLY, TRUSTED_CLIENT_CERTIFICATE_REQUIRED or ALLOW_UNENCRYPTED_AND_ENCRYPTED."\n  }\n}\n\nvariable "workload_sa_email" {\n  description = "Workload runtime service account email to grant cloudsql.client role"\n  type        = string\n  default     = ""\n}\n\nvariable "grant_workload_secret_access" {\n  description = "Grant workload_sa_email roles/secretmanager.secretAccessor on the database password secret (requires workload_sa_email)"\n  type        = bool\n  default     = false\n}\n\nvariable "kms_key_name" {\n  description = "Cloud KMS CryptoKey resource name (CMEK) for the instance, in the instance\'s region. The Cloud SQL service agent needs roles/cloudkms.cryptoKeyEncrypterDecrypter on it. Set at creation only. null = Google-managed encryption."\n  type        = string\n  default     = null\n}\n'}, 'compute-cloudrun': {'main.tf': '# ==============================================================================\n# STACKVEND: COMPUTE ARCHETYPE - CLOUD RUN (SERVERLESS CONTAINER)\n# ==============================================================================\n# Enterprise-hardened Cloud Run v2 service module.\n# Enforces deletion_protection = false, standard health probes, and IAM invoker.\n# ==============================================================================\n\nterraform {\n  required_version = ">= 1.5.0"\n  required_providers {\n    google = {\n      source = "hashicorp/google"\n    }\n    google-beta = {\n      source = "hashicorp/google-beta"\n    }\n  }\n}\n\ndata "google_project" "workload_project" {\n  project_id = var.project_id\n}\n\nresource "google_cloud_run_v2_service" "app" {\n  provider            = google-beta\n  project             = var.project_id\n  name                = var.service_name != "" ? var.service_name : var.product_id\n  location            = var.region\n  ingress             = var.ingress\n  deletion_protection = false\n\n  launch_stage = (!var.allow_unauthenticated && var.enable_direct_iap) ? "BETA" : null\n  iap_enabled  = (!var.allow_unauthenticated && var.enable_direct_iap)\n\n  # StackVend FD-4I (lane 19 L19-5a): a private service with zero invokers fails at plan, loudly (never widened).\n  lifecycle {\n    precondition {\n      condition     = var.allow_unauthenticated || length(var.authorized_invoker_members) > 0\n      error_message = "A private Cloud Run service (allow_unauthenticated = false) needs at least one authorized_invoker_members entry; StackVend never widens it to allAuthenticatedUsers."\n    }\n  }\n\n  template {\n    service_account = var.service_account_email\n    timeout         = "300s"\n    encryption_key  = var.encryption_key # lane 14 PR-0b: CMEK for regulated profiles (null = Google-managed)\n\n    containers {\n      image = var.container_image != "" ? var.container_image : "us-central1-docker.pkg.dev/${var.project_id}/${var.product_id}/${var.service_name != "" ? var.service_name : var.product_id}:latest"\n      resources {\n        limits = {\n          cpu    = var.cpu_limit\n          memory = var.memory_limit\n        }\n        cpu_idle = var.cpu_idle\n      }\n      env {\n        name  = "PROJECT_ID"\n        value = var.project_id\n      }\n      # StackVend CLOUDRUN-GOOGLE-CLOUD-PROJECT-ENV (owner 11-10): Cloud Run sets no project variable, and Google client\n      # libraries and most generated code read GOOGLE_CLOUD_PROJECT. Emitted only when var.env_vars has no such key, so\n      # a caller\'s own value is the single entry (Cloud Run env names must be unique).\n      dynamic "env" {\n        for_each = contains(keys(var.env_vars), "GOOGLE_CLOUD_PROJECT") ? [] : [var.project_id]\n        content {\n          name  = "GOOGLE_CLOUD_PROJECT"\n          value = env.value\n        }\n      }\n      env {\n        name  = "ENVIRONMENT"\n        value = "prod"\n      }\n      env {\n        name  = "GOOGLE_CLIENT_ID"\n        value = var.oauth_client_id\n      }\n      env {\n        name  = "FIREBASE_API_KEY"\n        value = var.firebase_api_key\n      }\n      env {\n        name  = "FIREBASE_AUTH_DOMAIN"\n        value = var.firebase_auth_domain\n      }\n      dynamic "env" {\n        for_each = var.env_vars\n        content {\n          name  = env.key\n          value = env.value\n        }\n      }\n      startup_probe {\n        http_get {\n          path = var.health_check_path\n          port = 8080\n        }\n        initial_delay_seconds = 2\n        timeout_seconds      = 4\n        period_seconds       = 5\n        failure_threshold    = 20\n      }\n    }\n\n    scaling {\n      min_instance_count = var.min_instances\n      max_instance_count = var.max_instances\n    }\n\n    dynamic "vpc_access" {\n      for_each = var.vpc_access_connector != "" ? [1] : []\n      content {\n        connector = var.vpc_access_connector\n        egress    = var.vpc_egress\n      }\n    }\n  }\n}\n\nresource "google_cloud_run_v2_service_iam_member" "public_access" {\n  count    = var.allow_unauthenticated ? 1 : 0\n  project  = var.project_id\n  location = var.region\n  name     = google_cloud_run_v2_service.app.name\n  role     = "roles/run.invoker"\n  member   = "allUsers"\n}\n\nresource "google_cloud_run_v2_service_iam_member" "domain_access" {\n  for_each = var.allow_unauthenticated ? toset([]) : toset(var.authorized_invoker_members)\n  project  = var.project_id\n  location = var.region\n  name     = google_cloud_run_v2_service.app.name\n  role     = "roles/run.invoker"\n  member   = each.key\n}\n\n# StackVend FD-4CS-b: the IAP service agent of the workload project. A fresh project has no IAP agent until it is\n# created (or read) through the Service Usage API, so the invoker binding below waits for it. Direct IAP only.\nresource "google_project_service_identity" "iap_service_agent" {\n  provider = google-beta\n  count    = (!var.allow_unauthenticated && var.enable_direct_iap) ? 1 : 0\n  project  = var.project_id\n  service  = "iap.googleapis.com"\n}\n\n# IAP Service Agent Invoker (allows IAP proxy to invoke the Cloud Run container)\n# IAP-GATE-KNOWN-MEMBER: the agent\'s project number comes from var.project_number when the platform render sets it, so\n# the member is a real value in the plan the compliance gate reads. The data source in this module is read only at\n# apply on a first deploy (the platform\'s module-level depends_on on module.foundation defers it); it stays as the\n# fallback for a caller that does not set the input. Same project, same number, so the member string does not change.\nresource "google_cloud_run_v2_service_iam_member" "iap_agent_invoker" {\n  count      = (!var.allow_unauthenticated && var.enable_direct_iap) ? 1 : 0\n  project    = var.project_id\n  location   = var.region\n  name       = google_cloud_run_v2_service.app.name\n  role       = "roles/run.invoker"\n  member     = "serviceAccount:service-${var.project_number != "" ? var.project_number : data.google_project.workload_project.number}@gcp-sa-iap.iam.gserviceaccount.com"\n  depends_on = [google_project_service_identity.iap_service_agent]\n}\n\n# Enterprise IAP Web Accessors (grants corporate browser users access through IAP)\nresource "google_iap_web_cloud_run_service_iam_member" "iap_accessors" {\n  for_each               = (!var.allow_unauthenticated && var.enable_direct_iap) ? toset(var.authorized_invoker_members) : toset([])\n  project                = var.project_id\n  location               = var.region\n  cloud_run_service_name = google_cloud_run_v2_service.app.name\n  role                   = "roles/iap.httpsResourceAccessor"\n  member                 = each.key\n}\n\n# StackVend PUSH-TO-PRIVATE (owner 10-27): the workload\'s own Pub/Sub push subscriptions to this service sign with the\n# service accounts in push_service_accounts (platform-rendered from the typed intent, never an AI argument). A private\n# service lets exactly those identities in, and only the way its access mode needs: Direct IAP checks\n# roles/iap.httpsResourceAccessor on this service\'s IAP resource (Cloud Run then checks run.invoker on the IAP agent,\n# granted above); a private IAM-only service checks roles/run.invoker on the caller. Public services and an empty map\n# plan nothing.\nresource "google_iap_web_cloud_run_service_iam_member" "push_accessors" {\n  for_each               = (!var.allow_unauthenticated && var.enable_direct_iap) ? var.push_service_accounts : tomap({})\n  project                = var.project_id\n  location               = var.region\n  cloud_run_service_name = google_cloud_run_v2_service.app.name\n  role                   = "roles/iap.httpsResourceAccessor"\n  member                 = "serviceAccount:${each.value}"\n}\n\nresource "google_cloud_run_v2_service_iam_member" "push_invokers" {\n  for_each = (!var.allow_unauthenticated && !var.enable_direct_iap) ? var.push_service_accounts : tomap({})\n  project  = var.project_id\n  location = var.region\n  name     = google_cloud_run_v2_service.app.name\n  role     = "roles/run.invoker"\n  member   = "serviceAccount:${each.value}"\n}\n', 'outputs.tf': '# ==============================================================================\n# STACKVEND: COMPUTE ARCHETYPE - CLOUD RUN OUTPUTS\n# ==============================================================================\n\noutput "service_name" {\n  description = "Name of the Cloud Run v2 service"\n  value       = google_cloud_run_v2_service.app.name\n}\n\noutput "service_uri" {\n  description = "HTTPS URI of the deployed Cloud Run service"\n  value       = google_cloud_run_v2_service.app.uri\n}\n\noutput "service_id" {\n  description = "Resource ID of the Cloud Run service"\n  value       = google_cloud_run_v2_service.app.id\n}\n\noutput "iap_enabled" {\n  description = "Whether Direct IAP is enabled on the Cloud Run service"\n  value       = (!var.allow_unauthenticated && var.enable_direct_iap)\n}\n', 'variables.tf': '# ==============================================================================\n# STACKVEND: COMPUTE ARCHETYPE - CLOUD RUN VARIABLES\n# ==============================================================================\n\nvariable "project_id" {\n  description = "Target GCP Child Project ID"\n  type        = string\n}\n\nvariable "region" {\n  description = "GCP Region"\n  type        = string\n  default     = "us-central1"\n}\n\nvariable "product_id" {\n  description = "Workload Product ID"\n  type        = string\n}\n\nvariable "service_name" {\n  description = "Override name for Cloud Run service (defaults to product_id)"\n  type        = string\n  default     = ""\n}\n\nvariable "service_account_email" {\n  description = "Runtime service account email"\n  type        = string\n}\n\nvariable "container_image" {\n  description = "Container image URL"\n  type        = string\n  default     = ""\n}\n\nvariable "ingress" {\n  description = "Ingress traffic configuration"\n  type        = string\n  default     = "INGRESS_TRAFFIC_ALL"\n}\n\nvariable "allow_unauthenticated" {\n  description = "Allow unauthenticated public access to the Cloud Run service"\n  type        = bool\n  default     = true\n}\n\nvariable "enable_direct_iap" {\n  description = "Whether to enable native Direct Identity-Aware Proxy (IAP) on Cloud Run when allow_unauthenticated is false"\n  type        = bool\n  default     = false\n}\n\nvariable "authorized_invoker_members" {\n  description = "List of authorized IAM members when unauthenticated access is disabled (e.g. [\'domain:mycompany.com\', \'serviceAccount:sa-caller@...\'])"\n  type        = list(string)\n  default     = []\n\n  # StackVend FD-4I (lane 19 L19-5a): exact "<kind>:<value>" members only. allUsers / allAuthenticatedUsers (with or\n  # without a prefix), unprefixed strings and other kinds fail at plan; public access is allow_unauthenticated only.\n  validation {\n    condition = alltrue([\n      for m in var.authorized_invoker_members :\n      length(split(":", m)) >= 2\n      && contains(["user", "group", "serviceAccount", "domain"], split(":", m)[0])\n      && length(join(":", slice(split(":", m), 1, length(split(":", m))))) > 0\n      && !contains(["allUsers", "allAuthenticatedUsers"], join(":", slice(split(":", m), 1, length(split(":", m)))))\n    ])\n    error_message = "authorized_invoker_members entries must be user:, group:, serviceAccount: or domain: members; allUsers / allAuthenticatedUsers are never invokers of a private service."\n  }\n}\n\nvariable "cpu_limit" {\n  description = "CPU limit for container"\n  type        = string\n  default     = "1000m"\n}\n\nvariable "memory_limit" {\n  description = "Memory limit for container"\n  type        = string\n  default     = "512Mi"\n}\n\nvariable "health_check_path" {\n  description = "HTTP path for startup health probe"\n  type        = string\n  default     = "/health"\n}\n\nvariable "oauth_client_id" {\n  description = "Google OAuth 2.0 Web Client ID"\n  type        = string\n  default     = ""\n}\n\nvariable "firebase_api_key" {\n  description = "Firebase Browser API Key"\n  type        = string\n  default     = ""\n}\n\nvariable "firebase_auth_domain" {\n  description = "Firebase Auth Domain"\n  type        = string\n  default     = ""\n}\n\nvariable "min_instances" {\n  description = "Minimum number of warm instances (0 = scale to zero, 1+ = keep hot/warm)"\n  type        = number\n  default     = 0\n}\n\nvariable "max_instances" {\n  description = "Maximum number of instances for auto-scaling"\n  type        = number\n  default     = 10\n}\n\nvariable "cpu_idle" {\n  description = "Whether CPU is throttled when idle (true = request-based billing, false = always allocated)"\n  type        = bool\n  default     = true\n}\n\nvariable "env_vars" {\n  description = "Custom environment variables to pass to the container"\n  type        = map(string)\n  default     = {}\n}\n\nvariable "vpc_access_connector" {\n  description = "The ID or name of the Serverless VPC Access connector (e.g. google_vpc_access_connector.<name>.id)"\n  type        = string\n  default     = ""\n}\n\nvariable "vpc_egress" {\n  description = "VPC egress traffic routing policy: PRIVATE_RANGES_ONLY or ALL_TRAFFIC"\n  type        = string\n  default     = "PRIVATE_RANGES_ONLY"\n}\n\nvariable "encryption_key" {\n  description = "Cloud KMS CryptoKey resource name for the service\'s customer-managed encryption (CMEK), in the service\'s region. null = Google-managed encryption."\n  type        = string\n  default     = null\n}\n\nvariable "project_number" {\n  description = "IAP-GATE-KNOWN-MEMBER: the workload project\'s number, set by the platform render for a Direct IAP service so the IAP agent\'s invoker member is known at plan. Empty = the module reads it with its own data source."\n  type        = string\n  default     = ""\n\n  validation {\n    condition     = var.project_number == "" || can(regex("^[0-9]+$", var.project_number))\n    error_message = "project_number must be the numeric project number (or empty)."\n  }\n}\n\nvariable "push_service_accounts" {\n  description = "PUSH-TO-PRIVATE: the service accounts this workload\'s own Pub/Sub push subscriptions to this service sign their OIDC tokens with, keyed by a stable platform label (keys known at plan; values may be computed). A private service admits exactly these: the IAP accessor role with Direct IAP, run.invoker without it. Ignored for a public service. Rendered by the platform from the typed intent."\n  type        = map(string)\n  default     = {}\n\n  validation {\n    condition     = alltrue([for e in values(var.push_service_accounts) : can(regex("^[a-z0-9-]+@[a-z0-9.-]+\\\\.gserviceaccount\\\\.com$", e))])\n    error_message = "push_service_accounts values must be bare service account emails (no member prefix)."\n  }\n}\n'}, 'compute-gke-autopilot': {'main.tf': '# ==============================================================================\n# STACKVEND: COMPUTE ARCHETYPE - GKE AUTOPILOT (MANAGED KUBERNETES)\n# ==============================================================================\n# Provisions a Google-managed GKE Autopilot cluster with private nodes and\n# deletion_protection = false for automated lifecycle management.\n# ==============================================================================\n\nresource "google_container_cluster" "autopilot" {\n  project             = var.project_id\n  name                = var.cluster_name != "" ? var.cluster_name : "gke-${replace(var.product_id, "_", "-")}"\n  location            = var.region\n  enable_autopilot    = true\n  deletion_protection = false\n\n  network    = var.network\n  subnetwork = var.subnetwork != "" ? var.subnetwork : null\n\n  ip_allocation_policy {}\n\n  private_cluster_config {\n    enable_private_nodes    = true\n    enable_private_endpoint = false\n  }\n\n  # Lane 14 PR-0b: application-layer secrets encryption with a CMEK for regulated profiles (no block = default).\n  dynamic "database_encryption" {\n    for_each = var.database_encryption_key != null ? [1] : []\n    content {\n      state    = "ENCRYPTED"\n      key_name = var.database_encryption_key\n    }\n  }\n}\n', 'outputs.tf': '# ==============================================================================\n# STACKVEND: COMPUTE ARCHETYPE - GKE AUTOPILOT OUTPUTS\n# ==============================================================================\n\noutput "cluster_name" {\n  description = "Name of the GKE Autopilot cluster"\n  value       = google_container_cluster.autopilot.name\n}\n\noutput "cluster_endpoint" {\n  description = "Cluster Kubernetes control plane endpoint"\n  value       = google_container_cluster.autopilot.endpoint\n}\n\noutput "cluster_id" {\n  description = "Resource ID of the GKE cluster"\n  value       = google_container_cluster.autopilot.id\n}\n\noutput "cluster_ca_certificate" {\n  description = "Public certificate authority of the cluster control plane"\n  value       = google_container_cluster.autopilot.master_auth[0].cluster_ca_certificate\n  sensitive   = true\n}\n', 'variables.tf': '# ==============================================================================\n# STACKVEND: COMPUTE ARCHETYPE - GKE AUTOPILOT VARIABLES\n# ==============================================================================\n\nvariable "project_id" {\n  description = "Target GCP Child Project ID"\n  type        = string\n}\n\nvariable "region" {\n  description = "GCP Region"\n  type        = string\n  default     = "us-central1"\n}\n\nvariable "product_id" {\n  description = "Workload Product ID"\n  type        = string\n}\n\nvariable "network" {\n  description = "VPC network name"\n  type        = string\n  default     = "default"\n}\n\nvariable "subnetwork" {\n  description = "VPC subnetwork name (optional)"\n  type        = string\n  default     = ""\n}\n\nvariable "cluster_name" {\n  description = "Optional custom name for the GKE Autopilot cluster. If empty, derived from product_id."\n  type        = string\n  default     = ""\n}\n\nvariable "database_encryption_key" {\n  description = "Cloud KMS CryptoKey resource name for application-layer secrets encryption (CMEK), in the cluster\'s region. null = default encryption."\n  type        = string\n  default     = null\n}\n'}, 'scheduling-cron': {'main.tf': 'terraform {\n  required_version = ">= 1.5.0"\n  required_providers {\n    google = {\n      source = "hashicorp/google"\n    }\n  }\n}\n\nresource "google_cloud_scheduler_job" "job" {\n  project     = var.project_id\n  region      = var.region\n  name        = "${var.project_id}-${var.job_name_suffix}"\n  description = "Scheduled cron job managed by StackVend"\n  schedule    = var.schedule\n  time_zone   = var.time_zone\n\n  http_target {\n    http_method = var.http_method\n    uri         = var.target_uri\n\n    dynamic "oidc_token" {\n      for_each = var.service_account_email != "" ? [1] : []\n      content {\n        service_account_email = var.service_account_email\n        # SCHEDULING-CRON-AUDIENCE: null leaves the attribute unset, so the token\'s audience stays the target URI.\n        audience = var.audience\n      }\n    }\n  }\n\n  lifecycle {\n    # SCHEDULING-CRON-AUDIENCE: an audience is carried by the OIDC token only; without a service account there is no\n    # token, so a set audience would be dropped silently. Fail the plan instead.\n    precondition {\n      condition     = var.audience == null || var.service_account_email != ""\n      error_message = "scheduling-cron: audience is set but service_account_email is empty; the job sends no OIDC token, so the audience would be ignored. Set service_account_email or leave audience null."\n    }\n  }\n}\n', 'outputs.tf': 'output "job_name" {\n  description = "Name of the Cloud Scheduler job"\n  value       = google_cloud_scheduler_job.job.name\n}\n\noutput "job_id" {\n  description = "Resource ID of the Cloud Scheduler job"\n  value       = google_cloud_scheduler_job.job.id\n}\n', 'variables.tf': 'variable "project_id" {\n  description = "GCP Project ID"\n  type        = string\n}\n\nvariable "region" {\n  description = "GCP Region"\n  type        = string\n  default     = "us-central1"\n}\n\nvariable "job_name_suffix" {\n  description = "Suffix for the cron job name (e.g. \'nightly-sync\')"\n  type        = string\n  default     = "sync"\n}\n\nvariable "schedule" {\n  description = "Cron schedule expression (e.g. \'0 2 * * *\' for 2 AM daily)"\n  type        = string\n  default     = "0 0 * * *"\n}\n\nvariable "time_zone" {\n  description = "Time zone for cron schedule"\n  type        = string\n  default     = "UTC"\n}\n\nvariable "target_uri" {\n  description = "Target HTTP URI to invoke (e.g. Cloud Run service URL + \'/jobs/sync\')"\n  type        = string\n}\n\nvariable "http_method" {\n  description = "HTTP method to invoke"\n  type        = string\n  default     = "POST"\n}\n\nvariable "service_account_email" {\n  description = "Service account email for OIDC token authorization"\n  type        = string\n  default     = ""\n}\n\nvariable "audience" {\n  description = "OIDC token audience (e.g. the exact audience constant the target service verifies). Null keeps the default: the target URI. Needs service_account_email."\n  type        = string\n  default     = null\n  validation {\n    condition     = var.audience == null ? true : (length(var.audience) > 0 && trimspace(var.audience) == var.audience)\n    error_message = "audience must be null or a non-empty string without leading or trailing whitespace."\n  }\n}\n'}, 'workload_auth': {'main.tf': '# ==============================================================================\n# STACKVEND: WORKLOAD AUTHENTICATION MODULE (IDENTITY PLATFORM / FIREBASE)\n# ==============================================================================\n# Automates Google Cloud Identity Platform provisioning and Google IdP configuration\n# for vended child projects using centralized or injected OAuth 2.0 credentials.\n# ==============================================================================\n\nterraform {\n  required_version = ">= 1.5.0"\n  required_providers {\n    google = {\n      source  = "hashicorp/google"\n      version = "~> 6.0"\n    }\n  }\n}\n\n# ------------------------------------------------------------------------------\n# 1. API Enablement: Identity Toolkit API\n# ------------------------------------------------------------------------------\nresource "google_project_service" "identitytoolkit" {\n  project                    = var.project_id\n  service                    = "identitytoolkit.googleapis.com"\n  disable_on_destroy         = false\n  disable_dependent_services = false\n}\n\n# ------------------------------------------------------------------------------\n# 2. Identity Platform Configuration\n# ------------------------------------------------------------------------------\nresource "google_identity_platform_config" "auth_config" {\n  depends_on = [google_project_service.identitytoolkit]\n  project    = var.project_id\n\n  sign_in {\n    allow_duplicate_emails = false\n\n    email {\n      enabled           = var.enable_email_password_auth\n      password_required = var.enable_email_password_auth\n    }\n\n    anonymous {\n      enabled = var.enable_anonymous_auth\n    }\n  }\n\n  authorized_domains = concat(\n    [\n      "localhost",\n      "${var.project_id}.firebaseapp.com",\n      "${var.project_id}.web.app",\n    ],\n    var.additional_authorized_domains\n  )\n}\n\n# ------------------------------------------------------------------------------\n# 3. Google OAuth 2.0 Identity Provider (IdP) Binding\n# ------------------------------------------------------------------------------\nresource "google_identity_platform_default_supported_idp_config" "google_idp" {\n  depends_on    = [google_identity_platform_config.auth_config]\n  project       = var.project_id\n  idp_id        = "google.com"\n  enabled       = true\n  client_id     = var.oauth_client_id\n  client_secret = var.oauth_client_secret\n}\n', 'outputs.tf': 'output "identity_platform_config_name" {\n  description = "The resource name of the Identity Platform configuration."\n  value       = google_identity_platform_config.auth_config.name\n}\n\noutput "google_idp_name" {\n  description = "The resource name of the Google IdP configuration."\n  value       = google_identity_platform_default_supported_idp_config.google_idp.name\n}\n\noutput "authorized_domains" {\n  description = "The list of authorized domains for OAuth redirects."\n  value       = google_identity_platform_config.auth_config.authorized_domains\n}\n', 'variables.tf': 'variable "project_id" {\n  description = "The target GCP project ID where Identity Platform will be configured."\n  type        = string\n}\n\nvariable "oauth_client_id" {\n  description = "Google OAuth 2.0 Client ID (injected from Central Platform Secret Manager)."\n  type        = string\n}\n\nvariable "oauth_client_secret" {\n  description = "Google OAuth 2.0 Client Secret (injected from Central Platform Secret Manager)."\n  type        = string\n  sensitive   = true\n}\n\nvariable "enable_email_password_auth" {\n  description = "Whether to enable Email and Password sign-in."\n  type        = bool\n  default     = true\n}\n\nvariable "enable_anonymous_auth" {\n  description = "Whether to enable anonymous guest sign-in."\n  type        = bool\n  default     = false\n}\n\nvariable "additional_authorized_domains" {\n  description = "List of additional web domains authorized for OAuth redirects (e.g. custom domains, Cloud Run URL)."\n  type        = list(string)\n  default     = []\n}\n'}, 'observability-alerts': {'main.tf': 'terraform {\n  required_version = ">= 1.5.0"\n  required_providers {\n    google = {\n      source = "hashicorp/google"\n    }\n  }\n}\n\nresource "google_monitoring_alert_policy" "alert" {\n  project      = var.project_id\n  display_name = "${var.project_id}-${var.alert_name_suffix}"\n  combiner     = "OR"\n\n  conditions {\n    display_name = "Metric condition for ${var.alert_name_suffix}"\n    condition_threshold {\n      filter          = var.filter\n      duration        = var.duration\n      comparison      = "COMPARISON_GT"\n      threshold_value = var.threshold_value\n\n      aggregations {\n        alignment_period   = "60s"\n        per_series_aligner = "ALIGN_RATE"\n      }\n    }\n  }\n\n  notification_channels = var.notification_channels\n}\n', 'outputs.tf': 'output "alert_policy_id" {\n  description = "Resource ID of the Cloud Monitoring alert policy"\n  value       = google_monitoring_alert_policy.alert.id\n}\n\noutput "alert_policy_name" {\n  description = "Display name of the alert policy"\n  value       = google_monitoring_alert_policy.alert.display_name\n}\n', 'variables.tf': 'variable "project_id" {\n  description = "GCP Project ID"\n  type        = string\n}\n\nvariable "alert_name_suffix" {\n  description = "Suffix for the alert policy display name (e.g. \'5xx-errors\', \'high-latency\')"\n  type        = string\n  default     = "high-error-rate"\n}\n\nvariable "filter" {\n  description = "Cloud Monitoring metric filter expression"\n  type        = string\n  default     = "metric.type=\\"run.googleapis.com/request_count\\" resource.type=\\"cloud_run_revision\\" metric.labels.response_code_class=\\"5xx\\""\n}\n\nvariable "duration" {\n  description = "Duration over which metric violation is measured (e.g. \'300s\')"\n  type        = string\n  default     = "300s"\n}\n\nvariable "threshold_value" {\n  description = "Threshold value above which the alert triggers"\n  type        = number\n  default     = 5\n}\n\nvariable "notification_channels" {\n  description = "List of Cloud Monitoring notification channel IDs"\n  type        = list(string)\n  default     = []\n}\n'}, 'compute-gce-worker': {'main.tf': '# ==============================================================================\n# STACKVEND: COMPUTE ARCHETYPE - GCE WORKER (ON-DEMAND VM FROM A TEMPLATE)\n# ==============================================================================\n# An instance template that a Cloud Run launcher starts VMs from at runtime (lane 10, register L10-s/t/u):\n# Spot e2-micro by default, deleted after max_run_duration_seconds (default 24 h), startup script, its own service\n# account, no VM at rest, no external IP, no inbound firewall rule, no Cloud NAT. Network (L10-u2): the workload\'s\n# existing subnetwork when the platform passes one (use_existing_subnetwork + subnetwork_id), else its own VPC + subnet\n# on the IPAM range with Private Google Access.\n# The launcher gets roles/compute.instanceAdmin.v1 only under an IAM condition limited to this worker\'s instances,\n# their boot disks, its templates and its subnetwork, plus roles/iam.serviceAccountUser on the worker SA only.\n# ==============================================================================\n\n# RT F2: the default zone is a zone of the region that exists and is UP (names are sorted: deterministic per region),\n# never a guessed "<region>-a" (us-east1 / europe-west1 have none).\ndata "google_compute_zones" "available" {\n  project = var.project_id\n  region  = var.region\n  status  = "UP"\n}\n\nlocals {\n  short           = replace(substr(var.worker_name, 0, 25), "/-+$/", "")\n  base            = "gcew-${local.short}"\n  zone            = var.zone != "" ? var.zone : data.google_compute_zones.available.names[0]\n  instance_prefix = "gcew-${var.worker_name}-"\n  own_network     = var.use_existing_subnetwork ? 0 : 1\n  subnetwork      = var.use_existing_subnetwork ? var.subnetwork_id : one(google_compute_subnetwork.worker[*].id)\n}\n\nresource "google_service_account" "worker" {\n  project      = var.project_id\n  account_id   = local.base\n  display_name = "GCE worker ${var.worker_name} of ${var.product_id}"\n}\n\nresource "google_project_iam_member" "worker_log_writer" {\n  project = var.project_id\n  role    = "roles/logging.logWriter"\n  member  = "serviceAccount:${google_service_account.worker.email}"\n}\n\nresource "google_compute_network" "worker" {\n  count                   = local.own_network\n  project                 = var.project_id\n  name                    = "${local.base}-net"\n  auto_create_subnetworks = false\n}\n\nresource "google_compute_subnetwork" "worker" {\n  count                    = local.own_network\n  project                  = var.project_id\n  name                     = "${local.base}-subnet"\n  region                   = var.region\n  network                  = google_compute_network.worker[0].id\n  ip_cidr_range            = var.subnet_cidr\n  private_ip_google_access = true\n\n  lifecycle {\n    ignore_changes = [secondary_ip_range]\n    precondition {\n      condition     = var.subnet_cidr != ""\n      error_message = "compute-gce-worker: subnet_cidr (the IPAM fact var.subnet_cidr) is required for its own subnet."\n    }\n  }\n}\n\nresource "google_compute_instance_template" "worker" {\n  project      = var.project_id\n  name_prefix  = "${local.base}-"\n  machine_type = var.machine_type\n  labels = {\n    stackvend-worker = local.short\n  }\n\n  scheduling {\n    provisioning_model          = var.spot ? "SPOT" : "STANDARD"\n    preemptible                 = var.spot\n    automatic_restart           = false\n    on_host_maintenance         = "TERMINATE"\n    instance_termination_action = var.spot ? "DELETE" : null\n\n    # GCE-WORKER-MAX-RUN-DURATION: a Spot worker is deleted after max_run_duration_seconds even when its startup\n    # script never powers it off (a runaway batch VM otherwise bills forever). Spot only: a Spot VM can already be\n    # deleted at any moment by preemption, so a time bound changes no guarantee the worker had; a standard worker\n    # (spot = false) keeps an unbounded run time. null = no bound. VMs that instances.insert creates from this\n    # template (sourceInstanceTemplate) inherit the setting.\n    dynamic "max_run_duration" {\n      for_each = var.spot && var.max_run_duration_seconds != null ? [var.max_run_duration_seconds] : []\n      content {\n        seconds = max_run_duration.value\n      }\n    }\n  }\n\n  disk {\n    source_image = var.boot_image\n    disk_type    = var.disk_type\n    disk_size_gb = var.disk_size_gb\n    auto_delete  = true\n    boot         = true\n  }\n\n  network_interface {\n    subnetwork = local.subnetwork\n    # No access_config: no external IP (Google APIs through Private Google Access).\n  }\n\n  metadata = merge(var.env_vars, {\n    "startup-script" = var.startup_script\n    "enable-oslogin" = "TRUE"\n  })\n\n  service_account {\n    email  = google_service_account.worker.email\n    scopes = ["cloud-platform"]\n  }\n\n  lifecycle {\n    create_before_destroy = true\n    precondition {\n      condition     = !var.use_existing_subnetwork || var.subnetwork_id != ""\n      error_message = "compute-gce-worker: use_existing_subnetwork needs subnetwork_id (projects/<p>/regions/<r>/subnetworks/<n>)."\n    }\n  }\n}\n\n# ------------------------------------------------------------------------------\n# Launcher: conditional instanceAdmin (this worker\'s instances, boot disks, templates, subnetwork) + actAs worker SA\n# ------------------------------------------------------------------------------\nresource "google_project_iam_member" "launcher_instance_admin" {\n  count   = length(var.launcher_service_account_emails)\n  project = var.project_id\n  role    = "roles/compute.instanceAdmin.v1"\n  member  = "serviceAccount:${var.launcher_service_account_emails[count.index]}"\n\n  condition {\n    title       = "${local.base}-launch"\n    description = "Only GCE worker ${var.worker_name}: its instances, their boot disks, its templates, its subnetwork"\n    expression = join(" || ", [\n      "resource.name.startsWith(\\"projects/${var.project_id}/zones/${local.zone}/instances/${local.instance_prefix}\\")",\n      "resource.name.startsWith(\\"projects/${var.project_id}/zones/${local.zone}/disks/${local.instance_prefix}\\")",\n      "resource.name.startsWith(\\"projects/${var.project_id}/global/instanceTemplates/${local.base}-\\")",\n      "resource.name == \\"${local.subnetwork}\\"",\n    ])\n  }\n}\n\nresource "google_service_account_iam_member" "launcher_act_as" {\n  count              = length(var.launcher_service_account_emails)\n  service_account_id = google_service_account.worker.name\n  role               = "roles/iam.serviceAccountUser"\n  member             = "serviceAccount:${var.launcher_service_account_emails[count.index]}"\n}\n\n# ------------------------------------------------------------------------------\n# Worker resource access: granted to the worker\'s own SA, per resource\n# ------------------------------------------------------------------------------\nresource "google_storage_bucket_iam_member" "worker_bucket" {\n  count  = length(var.storage_buckets)\n  bucket = var.storage_buckets[count.index]\n  role   = "roles/storage.objectUser"\n  member = "serviceAccount:${google_service_account.worker.email}"\n}\n\nresource "google_pubsub_topic_iam_member" "worker_topic" {\n  count   = length(var.pubsub_topics)\n  project = var.project_id\n  topic   = var.pubsub_topics[count.index]\n  role    = "roles/pubsub.publisher"\n  member  = "serviceAccount:${google_service_account.worker.email}"\n}\n\nresource "google_pubsub_subscription_iam_member" "worker_subscription" {\n  count        = length(var.pubsub_subscriptions)\n  project      = var.project_id\n  subscription = var.pubsub_subscriptions[count.index]\n  role         = "roles/pubsub.subscriber"\n  member       = "serviceAccount:${google_service_account.worker.email}"\n}\n\nresource "google_secret_manager_secret_iam_member" "worker_secret" {\n  count     = length(var.secrets)\n  project   = var.project_id\n  secret_id = var.secrets[count.index]\n  role      = "roles/secretmanager.secretAccessor"\n  member    = "serviceAccount:${google_service_account.worker.email}"\n}\n\nresource "google_bigquery_dataset_iam_member" "worker_dataset" {\n  count      = length(var.bigquery_datasets)\n  project    = var.project_id\n  dataset_id = var.bigquery_datasets[count.index]\n  role       = "roles/bigquery.dataEditor"\n  member     = "serviceAccount:${google_service_account.worker.email}"\n}\n', 'outputs.tf': '# ==============================================================================\n# STACKVEND: COMPUTE ARCHETYPE - GCE WORKER OUTPUTS\n# ==============================================================================\n\noutput "instance_template_self_link" {\n  description = "Self-link of the instance template the launcher passes as sourceInstanceTemplate"\n  value       = google_compute_instance_template.worker.self_link\n}\n\noutput "instance_template_name" {\n  description = "Name of the current instance template"\n  value       = google_compute_instance_template.worker.name\n}\n\noutput "instance_name_prefix" {\n  description = "Launched instance names must start with this prefix (the launch grant is limited to it)"\n  value       = local.instance_prefix\n}\n\noutput "zone" {\n  description = "Zone the launcher creates worker VMs in"\n  value       = local.zone\n}\n\noutput "service_account_email" {\n  description = "Service account the worker VMs run as"\n  value       = google_service_account.worker.email\n}\n', 'variables.tf': '# ==============================================================================\n# STACKVEND: COMPUTE ARCHETYPE - GCE WORKER VARIABLES\n# ==============================================================================\n\nvariable "project_id" {\n  description = "Target GCP Child Project ID"\n  type        = string\n}\n\nvariable "region" {\n  description = "GCP Region"\n  type        = string\n  default     = "us-central1"\n}\n\nvariable "product_id" {\n  description = "Workload Product ID"\n  type        = string\n}\n\nvariable "worker_name" {\n  description = "Topology service name of this worker (RFC 1123 label, <= 40 chars)"\n  type        = string\n}\n\nvariable "zone" {\n  description = "Zone the launcher creates worker VMs in (empty: the first UP zone of the region)"\n  type        = string\n  default     = ""\n}\n\nvariable "subnet_cidr" {\n  description = "Own-subnet range: the platform IPAM fact var.subnet_cidr (never a literal); unused with an existing subnetwork"\n  type        = string\n  default     = ""\n}\n\nvariable "use_existing_subnetwork" {\n  description = "Join the workload\'s existing subnetwork (subnetwork_id) instead of creating a VPC + subnet"\n  type        = bool\n  default     = false\n}\n\nvariable "subnetwork_id" {\n  description = "Existing subnetwork id (projects/<p>/regions/<r>/subnetworks/<n>) when use_existing_subnetwork"\n  type        = string\n  default     = ""\n}\n\nvariable "machine_type" {\n  description = "GCE machine type"\n  type        = string\n  default     = "e2-micro"\n}\n\nvariable "spot" {\n  description = "Spot provisioning (deleted on preemption or after max_run_duration_seconds)"\n  type        = bool\n  default     = true\n}\n\nvariable "max_run_duration_seconds" {\n  description = "Spot workers only: seconds after which Compute Engine deletes a worker VM (default 86400 = 24 h; null = no bound; 30 to 10368000). Standard workers (spot = false) are never bounded"\n  type        = number\n  default     = 86400\n  nullable    = true\n\n  validation {\n    condition = var.max_run_duration_seconds == null ? true : (\n      var.max_run_duration_seconds >= 30 && var.max_run_duration_seconds <= 10368000 &&\n      floor(var.max_run_duration_seconds) == var.max_run_duration_seconds\n    )\n    error_message = "compute-gce-worker: max_run_duration_seconds must be null or a whole number of seconds from 30 to 10368000 (120 days)."\n  }\n}\n\nvariable "boot_image" {\n  description = "Boot disk image"\n  type        = string\n  default     = "debian-cloud/debian-12"\n}\n\nvariable "disk_type" {\n  description = "Boot disk type"\n  type        = string\n  default     = "pd-standard"\n}\n\nvariable "disk_size_gb" {\n  description = "Boot disk size in GB"\n  type        = number\n  default     = 10\n}\n\nvariable "startup_script" {\n  description = "Startup script of every VM launched from the template (default: power off at once)"\n  type        = string\n  default     = "#!/bin/bash\\n# StackVend gce-worker: no worker script was provided; power off.\\npoweroff\\n"\n}\n\nvariable "env_vars" {\n  description = "Settings the worker reads from instance metadata attributes (key -> value)"\n  type        = map(string)\n  default     = {}\n}\n\nvariable "launcher_service_account_emails" {\n  description = "Runtime service accounts allowed to launch this worker (conditional instanceAdmin + actAs on the worker SA)"\n  type        = list(string)\n  default     = []\n}\n\nvariable "storage_buckets" {\n  description = "Bucket names the worker SA may read and write objects in (roles/storage.objectUser)"\n  type        = list(string)\n  default     = []\n}\n\nvariable "pubsub_topics" {\n  description = "Topic names the worker SA may publish to (roles/pubsub.publisher)"\n  type        = list(string)\n  default     = []\n}\n\nvariable "pubsub_subscriptions" {\n  description = "Subscription names the worker SA may pull from (roles/pubsub.subscriber)"\n  type        = list(string)\n  default     = []\n}\n\nvariable "secrets" {\n  description = "Secret ids the worker SA may read (roles/secretmanager.secretAccessor)"\n  type        = list(string)\n  default     = []\n}\n\nvariable "bigquery_datasets" {\n  description = "Dataset ids the worker SA may edit (roles/bigquery.dataEditor)"\n  type        = list(string)\n  default     = []\n}\n'}, 'networking-vpc-connector': {'main.tf': '# ==============================================================================\n# STACKVEND: NETWORKING ARCHETYPE - SERVERLESS VPC ACCESS CONNECTOR (FD-4BH)\n# ==============================================================================\n# One Serverless VPC Access connector, so Cloud Run services reach private IPs in\n# the workload VPC (Cloud SQL, Memorystore Redis, AlloyDB over Private Services\n# Access; a peered Vertex AI endpoint). Pass the `id` output to compute-cloudrun\'s\n# `vpc_access_connector` input.\n#\n# A separate module, not a block inside networking-vpc: networking-vpc stays\n# unchanged (no plan diff for a workload that uses it), and `region` and\n# `connector_cidr` are required here with no default. The /28 range is the\n# workload\'s IPAM allocation (var.connector_cidr of the workload root); the region\n# is the workload\'s var.region. No region or CIDR literal lives in this module.\n# On typed infrastructure the platform renders the call itself\n# (module.stackvend_connector); the AI never writes it.\n# ==============================================================================\n\nterraform {\n  required_version = ">= 1.5.0"\n  required_providers {\n    google = {\n      source  = "hashicorp/google"\n      version = ">= 5.0.0"\n    }\n  }\n}\n\nresource "google_vpc_access_connector" "connector" {\n  project       = var.project_id\n  name          = var.name\n  region        = var.region\n  network       = var.network\n  ip_cidr_range = var.connector_cidr\n  machine_type  = var.machine_type\n  min_instances = var.min_instances\n  max_instances = var.max_instances\n\n  lifecycle {\n    precondition {\n      condition     = var.min_instances < var.max_instances\n      error_message = "min_instances must be lower than max_instances."\n    }\n  }\n}\n', 'outputs.tf': '# ==============================================================================\n# STACKVEND: NETWORKING ARCHETYPE - SERVERLESS VPC ACCESS CONNECTOR OUTPUTS\n# ==============================================================================\n\noutput "id" {\n  description = "Connector ID (projects/PROJECT/locations/REGION/connectors/NAME). Pass it to compute-cloudrun\'s vpc_access_connector input."\n  value       = google_vpc_access_connector.connector.id\n}\n\noutput "name" {\n  description = "Connector name"\n  value       = google_vpc_access_connector.connector.name\n}\n\noutput "self_link" {\n  description = "Connector self link"\n  value       = google_vpc_access_connector.connector.self_link\n}\n\noutput "region" {\n  description = "Region the connector serves"\n  value       = google_vpc_access_connector.connector.region\n}\n\noutput "ip_cidr_range" {\n  description = "The /28 range the connector uses (the IPAM connector allocation)"\n  value       = google_vpc_access_connector.connector.ip_cidr_range\n}\n', 'variables.tf': '# ==============================================================================\n# STACKVEND: NETWORKING ARCHETYPE - SERVERLESS VPC ACCESS CONNECTOR VARIABLES\n# ==============================================================================\n# region and connector_cidr have no default: the caller passes its var.region and\n# the IPAM connector allocation (var.connector_cidr). AGENTS.md invariant 3.\n\nvariable "project_id" {\n  description = "Target GCP child project ID"\n  type        = string\n}\n\nvariable "region" {\n  description = "GCP region of the connector (the caller\'s var.region). Must be the region of the Cloud Run services that use it."\n  type        = string\n\n  validation {\n    condition     = length(trimspace(var.region)) > 0\n    error_message = "region must be the workload region (var.region of the caller)."\n  }\n}\n\nvariable "network" {\n  description = "Name or self link of the VPC network the connector attaches to (for example networking-vpc\'s network_name output)."\n  type        = string\n\n  validation {\n    condition     = length(trimspace(var.network)) > 0\n    error_message = "network must be a non-empty VPC network name or self link."\n  }\n}\n\nvariable "connector_cidr" {\n  description = "Unreserved /28 IPv4 range for the connector: the workload\'s IPAM connector allocation (var.connector_cidr). Must not overlap a subnet of the network."\n  type        = string\n\n  validation {\n    condition     = can(cidrnetmask(var.connector_cidr)) && can(cidrhost(var.connector_cidr, 0)) && try(split("/", var.connector_cidr)[1] == "28", false)\n    error_message = "connector_cidr must be an IPv4 CIDR with a /28 prefix (the size Serverless VPC Access requires)."\n  }\n\n  validation {\n    condition     = try(cidrhost(var.connector_cidr, 0) == split("/", var.connector_cidr)[0], false)\n    error_message = "connector_cidr must be the network address of its /28 (host bits zero)."\n  }\n}\n\nvariable "name" {\n  description = "Connector name: 2 to 25 characters, lowercase letters, digits and hyphens, starting with a letter and not ending with a hyphen. Unique per region in the project."\n  type        = string\n  default     = "vpc-connector"\n\n  validation {\n    condition     = can(regex("^[a-z][-a-z0-9]{0,23}[a-z0-9]$", var.name))\n    error_message = "name must match ^[a-z][-a-z0-9]{0,23}[a-z0-9]$ (RFC 1123 label, at most 25 characters)."\n  }\n}\n\nvariable "machine_type" {\n  description = "Machine type of the connector instances: f1-micro, e2-micro or e2-standard-4."\n  type        = string\n  default     = "e2-micro"\n\n  validation {\n    condition     = contains(["f1-micro", "e2-micro", "e2-standard-4"], var.machine_type)\n    error_message = "machine_type must be one of f1-micro, e2-micro or e2-standard-4."\n  }\n}\n\nvariable "min_instances" {\n  description = "Minimum number of connector instances (2 to 9). Must be lower than max_instances."\n  type        = number\n  default     = 2\n\n  validation {\n    condition     = var.min_instances >= 2 && var.min_instances <= 9 && floor(var.min_instances) == var.min_instances\n    error_message = "min_instances must be a whole number from 2 to 9."\n  }\n}\n\nvariable "max_instances" {\n  description = "Maximum number of connector instances (3 to 10). Must be greater than min_instances."\n  type        = number\n  default     = 3\n\n  validation {\n    condition     = var.max_instances >= 3 && var.max_instances <= 10 && floor(var.max_instances) == var.max_instances\n    error_message = "max_instances must be a whole number from 3 to 10."\n  }\n}\n'}}
